content[195]=[[["Tina has a new small house.", "Tina tem uma casa nova e pequena."], ["She needs a bookcase and a table.", "Ela precisa de uma estante e de uma mesa."], ["She also needs to buy a cupboard.", "Ela também precisa comprar um armário."], ["“I need drawers,” she thinks.", "“Eu preciso de gavetas”, ela pensa."], ["Then she needs to call Ravi for help.", "Depois ela precisa ligar para o Ravi pedindo ajuda."]], [["What do you need?", "O que você precisa?"], ["I need a bookcase and some drawers.", "Preciso de uma estante e de gavetas."], ["Do you need to go to the shop?", "Você precisa ir à loja?"], ["No, I need to go home.", "Não, eu preciso ir para casa."], ["Is your house empty?", "Sua casa está vazia?"], ["No, but I need four more things.", "Não, mas preciso de mais quatro coisas."], ["Do you need any help?", "Você precisa de ajuda?"], ["Yes, I need to carry the cupboard.", "Sim, preciso carregar o armário."]], ["Palavra need", "O vogal é longo: NIID. O d final é suave.", ["need", "I need help."]], ["I need ___ the shop.", "to go to", "go to", "Preciso ir à loja.", "Need to + verbo: need to go."]];
