content[196]=[[["Lou looks for fish at the market.", "Lou procura peixe na feira."], ["“Is there any salmon?” he asks.", "“Tem salmão?”, ele pergunta."], ["The seller opens a big cold box.", "O vendedor abre uma caixa fria e grande."], ["There is not any fresh salmon today.", "Hoje não tem salmão fresco."], ["But there is some fresh seafood.", "Mas tem frutos do mar frescos."]], [["Is there any fresh fish?", "Tem peixe fresco?"], ["Yes, it is in the cold box.", "Tem, está na caixa fria."], ["Is there any salmon?", "Tem salmão?"], ["There is not any salmon today.", "Hoje não tem salmão."], ["Is there any seafood?", "Tem frutos do mar?"], ["Yes, there is some here.", "Tem sim, aqui."], ["Are there any cherries?", "Tem cerejas?"], ["Yes, there are some in the box.", "Tem sim, na caixa."]], ["Palavra fresh", "Comece com /fr/ e termine com /ʃ/: FRÉSH, sem vogal no fim.", ["fresh", "The fish is fresh."]], ["Is there ___ milk?", "any", "some", "Tem leite?", "Em perguntas, use any."]];
