content[197]=[[["Nico buys a lot of food for a party.", "Nico compra muita comida para uma festa."], ["He gets a doughnut for each friend.", "Ele pega uma rosquinha para cada amigo."], ["A few friends come at six.", "Alguns amigos chegam às seis."], ["They eat a lot of hamburgers.", "Eles comem muitos hambúrgueres."], ["Now there is only a little juice.", "Agora só resta um pouco de suco."]], [["Do you have a lot of food?", "Você tem muita comida?"], ["Yes, I have a lot. Take a hamburger.", "Tenho muita. Pegue um hambúrguer."], ["How many friends come?", "Quantos amigos vêm?"], ["A few friends come. Maybe six.", "Alguns amigos. Talvez seis."], ["Do you want a few sweets?", "Quer alguns doces?"], ["Yes, a few sweets, please.", "Sim, alguns doces, por favor."], ["Is there any juice left?", "Sobrou suco?"], ["Yes, a little. Take a few doughnuts.", "Sim, um pouco. Pegue algumas rosquinhas."]], ["Palavra doughnut", "Diga DÔU-nat; o gh não soa. O final é /t/.", ["doughnut", "I want a doughnut."]], ["I want ___ juice.", "a little", "a few", "Quero um pouco de suco.", "Juice é incontável: a little. A few só vai com contáveis."]];
