content[198]=[[["Ravi cooks a big curry for lunchtime.", "Ravi faz um curry grande para a hora do almoço."], ["He puts too much pepper in it.", "Ele põe pimenta demais."], ["The dish is not good now.", "O prato não está bom agora."], ["He does not have enough time.", "Ele não tem tempo suficiente."], ["So he goes to the shop again.", "Então ele vai à loja de novo."]], [["Is the curry good?", "O curry está bom?"], ["No, there is too much pepper.", "Não, tem pimenta demais."], ["Can we add water?", "Podemos pôr água?"], ["Yes, but we do not have enough water.", "Sim, mas não temos água suficiente."], ["Is the meat still raw?", "A carne ainda está crua?"], ["Yes, there is not enough time.", "Sim, não há tempo suficiente."], ["Do we have enough money for fish?", "Temos dinheiro suficiente para peixe?"], ["No, I do not have enough.", "Não, não tenho o suficiente."]], ["Palavra enough", "Diga i-NAF; o final é /f/, como em “fada”.", ["enough", "I have enough."]], ["There is ___ pepper.", "too much", "too many", "Tem pimenta demais.", "Pepper é incontável: too much. Too many é para contáveis."]];
