content[199]=[[["Lia takes a basket to the market.", "Lia leva uma cesta ao mercado."], ["She needs a kilo of ripe apples.", "Ela precisa de um quilo de maçãs maduras."], ["“How much are they?” “Two dollars a kilo.”", "“Quanto custam?” “Dois dólares o quilo.”"], ["She also wants a bag of chips.", "Ela também quer um pacote de batatas fritas."], ["She pays and gets her change.", "Ela paga e recebe o troco."]], [["How much are the apples?", "Quanto custam as maçãs?"], ["They are two dollars a kilo.", "Custam dois dólares o quilo."], ["How many kilos do you need?", "De quantos quilos você precisa?"], ["I need two kilos, please.", "Preciso de dois quilos, por favor."], ["Do you want a bag of chips too?", "Quer um pacote de batatas fritas também?"], ["Yes, I want a small bag.", "Sim, quero um pacote pequeno."], ["Is the tax in the price?", "O imposto está no preço?"], ["Yes, here is your change.", "Sim, aqui está o seu troco."]], ["Palavra ripe", "Diga RÁIP, com ai de “pai”. O p final é suave.", ["ripe", "The apples are ripe."]], ["How ___ is the cheese?", "much", "many", "Quanto custa o queijo?", "Para preço, use How much."]];
