content[200]=[[["Ava has a big family.", "A Ava tem uma família grande."], ["She has four cousins in the city.", "Ela tem quatro primos na cidade."], ["Her brother Noah has a niece and a nephew.", "O irmão dela, Noah, tem uma sobrinha e um sobrinho."], ["They have a babysitter on Friday.", "Eles têm uma babá na sexta."], ["Her mother has a cake for them.", "A mãe dela tem um bolo para eles."]], [["Do you have cousins?", "Você tem primos?"], ["Yes, I have four cousins.", "Tenho, quatro primos."], ["Do you have a niece too?", "Você também tem uma sobrinha?"], ["I have a niece and a nephew.", "Tenho uma sobrinha e um sobrinho."], ["Does your brother have a babysitter?", "Seu irmão tem uma babá?"], ["Yes, he has a good babysitter.", "Tem, uma babá muito boa."], ["Do you have a big family?", "Você tem uma família grande?"], ["Yes, we have ten at the table.", "Sim, somos dez à mesa."]], ["/h/ em have e has", "Sopre o ar de leve pela garganta, sem raspar: é quase só um suspiro antes da vogal.", ["has", "Ava has a sister."]], ["Ava ___ two sisters.", "has", "have", "Ava tem duas irmãs.", "Com nomes no singular (como he e she), o verbo é has."]];
