content[201]=[[["Ravi’s grandma has a small house.", "A avó do Ravi tem uma casa pequena."], ["Grandma’s cooker is very old.", "O fogão da vovó é muito velho."], ["The color of the dresser is blue.", "A cor da cômoda é azul."], ["Ravi’s bookshelf is next to it.", "A estante do Ravi fica ao lado dela."], ["Ravi likes his grandma’s kitchen.", "Ravi gosta da cozinha da avó dele."]], [["Whose cooker is that?", "De quem é aquele fogão?"], ["It is my grandma’s cooker.", "É o fogão da minha avó."], ["Is the dresser Ravi’s?", "A cômoda é do Ravi?"], ["No, it is Ben’s dresser.", "Não, é a cômoda do Ben."], ["Where is the key of the dresser?", "Onde está a chave da cômoda?"], ["It is on the shelf.", "Está na prateleira."], ["Is the color of the dresser blue?", "A cor da cômoda é azul?"], ["Yes, it is a very old dresser.", "Sim, é uma cômoda bem velha."]], ["O som /z/ final em ’s", "Em Ravi’s e Ben’s, o ’s soa como um z zumbido, com a voz ligada.", ["Ben’s", "Ben’s mother is here."]], ["This is ___ bag.", "Lia’s", "Lias", "Esta é a bolsa da Lia.", "Para mostrar o dono, junte ’s ao nome."]];
