content[202]=[[["Noah shows a photograph of his granny.", "Noah mostra uma fotografia da avó dele."], ["Her name is Rosa.", "O nome dela é Rosa."], ["His neighbour is next to her.", "O vizinho dele está ao lado dela."], ["Their house is by the lake.", "A casa deles fica perto do lago."], ["Noah says our pictures are old.", "Noah diz que nossas fotos são velhas."]], [["Is this your granny?", "Esta é a sua vovó?"], ["Yes, her name is Rosa.", "É, o nome dela é Rosa."], ["Is that your neighbour?", "Aquele é o seu vizinho?"], ["Yes, his name is Paulo.", "É, o nome dele é Paulo."], ["Where is their house?", "Onde fica a casa deles?"], ["Their house is near here.", "A casa deles fica perto daqui."], ["Are these pictures for our wall?", "Estas fotos são para a nossa parede?"], ["Yes, our wall is empty.", "Sim, nossa parede está vazia."]], ["/ð/ em their", "Ponha a ponta da língua entre os dentes e vibre a voz: their não começa com d.", ["their", "Their house is big."]], ["Ben has a dog. ___ name is Rex.", "His", "He", "Ben tem um cachorro. O nome dele é Rex.", "Antes de um substantivo, use his, não he."]];
