content[203]=[[["Peg finds a telephone on the table.", "Peg encontra um telefone na mesa."], ["“Whose telephone is this?” she asks.", "“De quem é este telefone?”, ela pergunta."], ["Tina says, “It is mine.”", "Tina diz: “É meu.”"], ["“And this bag is hers,” Peg says.", "“E esta bolsa é dela”, diz Peg."], ["“Those keys are yours, Ravi.”", "“Aquelas chaves são suas, Ravi.”"]], [["Whose umbrella is this?", "De quem é este guarda-chuva?"], ["It is mine.", "É meu."], ["Whose keys are these?", "De quem são estas chaves?"], ["They are yours, I think.", "São suas, eu acho."], ["Is this bag hers?", "Esta bolsa é dela?"], ["No, hers is the red bag.", "Não, a dela é a bolsa vermelha."], ["Are these books his?", "Estes livros são dele?"], ["No, they are not his. They are mine.", "Não, não são dele. São meus."]], ["/uː/ em whose", "Arredonde bem os lábios: whose soa como hooz, igual a who com z no fim.", ["whose", "Whose book is this?"]], ["This lamp is not yours. It is ___.", "mine", "me", "Este abajur não é seu. É meu.", "Mine substitui my + substantivo; me não serve."]];
