content[206]=[[["June shows Lia her new house.", "June mostra a Lia a casa nova dela."], ["There is a big kitchen downstairs.", "Há uma cozinha grande no andar de baixo."], ["There are two bedrooms upstairs.", "Há dois quartos no andar de cima."], ["There is a small garden behind the house.", "Há um jardim pequeno atrás da casa."], ["There are many flowers in the garden.", "Há muitas flores no jardim."]], [["Is there a kitchen?", "Tem cozinha?"], ["Yes, there is a big one.", "Sim, tem uma grande."], ["How many bedrooms are there?", "Quantos quartos tem?"], ["There are three bedrooms.", "Tem três quartos."], ["Is there a basement here?", "Tem porão aqui?"], ["Yes, there is one under the kitchen.", "Sim, tem um embaixo da cozinha."], ["Are there windows in the bedroom?", "Tem janelas no quarto?"], ["Yes, there are two windows.", "Sim, tem duas janelas."]], ["Acento em kitchen e bedroom", "Nas duas palavras, a primeira sílaba é forte: KIT-chen, BED-room.", ["kitchen", "The kitchen is clean."]], ["___ two windows in the room.", "There are", "There is", "Há duas janelas no quarto.", "Com plural, use there are."]];
