content[207]=[[["Tina looks at an apartment in the city.", "Tina visita um apartamento na cidade."], ["The kitchen is clean and bright.", "A cozinha é limpa e clara."], ["The street is very noisy.", "A rua é muito barulhenta."], ["The desk is messy, but the bed is new.", "A mesa está bagunçada, mas a cama é nova."], ["She wants a quiet house, so she says no.", "Ela quer uma casa silenciosa, então diz não."]], [["Is the house big or small?", "A casa é grande ou pequena?"], ["It is small, but it is new.", "É pequena, mas é nova."], ["Is the table wooden?", "A mesa é de madeira?"], ["Yes, but it is a little ugly.", "É, mas é um pouco feia."], ["Is the street noisy?", "A rua é barulhenta?"], ["Yes, it is noisy at night.", "Sim, é barulhenta à noite."], ["So the kitchen is new and clean?", "Então a cozinha é nova e limpa?"], ["Yes, new and very clean.", "Sim, nova e muito limpa."]], ["Vogal longa em clean", "Estique o som i: clean é lon-go, bem diferente do curto de in.", ["clean", "The room is clean."]], ["The windows are ___.", "big", "bigs", "As janelas são grandes.", "Adjetivos não mudam no plural."]];
