content[208]=[[["Peg has a new neighbor.", "Peg tem uma vizinha nova."], ["Peg asks who lives next door.", "Peg pergunta quem mora na casa ao lado."], ["The neighbor is June.", "A vizinha é a June."], ["June lives with her granddaughter.", "June mora com a neta dela."], ["June’s house is next to Peg’s house.", "A casa da June fica ao lado da casa da Peg."]], [["Who lives in this house?", "Quem mora nesta casa?"], ["My granddaughter lives here with me.", "Minha neta mora aqui comigo."], ["Where does your granddaughter work?", "Onde a sua neta trabalha?"], ["She works at a bank.", "Ela trabalha em um banco."], ["Who lives next door?", "Quem mora ao lado?"], ["A new neighbor lives there.", "Um vizinho novo mora lá."], ["So your granddaughter lives with you?", "Então a sua neta mora com você?"], ["Yes, she lives here with my dog.", "Sim, ela mora aqui com o meu cachorro."]], ["S final em lives", "Em lives, o s final soa como z, com a voz ligada: livz.", ["lives", "She lives here."]], ["___ next door?", "Who lives", "Who does live", "Quem mora ao lado?", "Com who no lugar do sujeito, use o verbo direto, sem does."]];
