content[209]=[[["Peg has a son and a daughter.", "Peg tem um filho e uma filha."], ["Her son is a teenager, and he is fifteen.", "O filho dela é adolescente e tem quinze anos."], ["Her daughter is the youngest, only six.", "A filha dela é a caçula, só tem seis."], ["There are four people in their house.", "Há quatro pessoas na casa deles."], ["Peg’s house is small, but it is clean.", "A casa da Peg é pequena, mas é limpa."]], [["Do you have a son?", "Você tem um filho?"], ["Yes, I have a son and a daughter.", "Sim, tenho um filho e uma filha."], ["How old is your son?", "Quantos anos tem o seu filho?"], ["He is fifteen years old.", "Ele tem quinze anos."], ["Whose room is this?", "De quem é este quarto?"], ["It is my daughter’s room.", "É o quarto da minha filha."], ["Is there a bed for your son?", "Tem uma cama para o seu filho?"], ["Yes, there are two beds there.", "Sim, tem duas camas lá."]], ["/s/ e /z/ em son e has", "Em son o s é seco; em has o s final vibra como z.", ["son", "My son has a dog."]], ["Peg ___ a son and a daughter.", "has", "have", "Peg tem um filho e uma filha.", "Com um nome no singular, o verbo é has."]];
