stories[209]=["Uma festa na casa do Nico", "Nico has a big family and a small house.~Nico tem uma família grande e uma casa pequena.|His grandmother has a party today.~A avó dele faz uma festa hoje.|Nico’s mother has a big cake in the kitchen.~A mãe do Nico tem um bolo grande na cozinha.|There are ten people in the house.~Há dez pessoas na casa.|Nico finds a phone under the sofa.~Nico acha um telefone embaixo do sofá.|Whose phone is this? It is his cousin’s.~De quem é este telefone? É do primo dele.|The cousin is nine years old.~O primo tem nove anos.|The house is noisy, but everyone is happy.~A casa é barulhenta, mas todos estão felizes.|Their house is old, but it is very clean.~A casa deles é velha, mas é muito limpa.|Nico loves his big family.~Nico adora a família grande dele."];
plans[210]={"title": "Ligando para a Ava", "file": "photo-coast-1.webp", "grammar": "It is + clima", "goal": "Descreva o tempo com It is + sunny, rainy, hot ou cold.", "words": [["rainy", "chuvoso"], ["foggy", "com neblina"], ["snowy", "com neve"], ["stormy", "com tempestade"]]};
content[210]=[[["Ravi calls Ava in Boston.", "Ravi liga para a Ava em Boston."], ["It is foggy in Boston today.", "Hoje tem neblina em Boston."], ["It is rainy at Ravi’s house.", "Está chovendo na casa do Ravi."], ["It is stormy at night, so Ava stays home.", "À noite tem tempestade, então a Ava fica em casa."], ["Ravi has tea because it is cold.", "Ravi toma chá porque está frio."]], [["Is it foggy today?", "Está com neblina hoje?"], ["Yes, it is foggy and cold.", "Sim, está com neblina e frio."], ["Is it rainy at your house?", "Está chovendo na sua casa?"], ["Yes, it is rainy again.", "Sim, está chovendo de novo."], ["Is it snowy there?", "Está nevando aí?"], ["No, it is not snowy.", "Não, não está nevando."], ["So it is foggy there?", "Então tem neblina aí?"], ["Yes, it is foggy all day.", "Sim, tem neblina o dia todo."]], ["/f/ em foggy", "Encoste os dentes de cima no lábio de baixo e solte o ar: foggy começa com f, não com p.", ["foggy", "It is foggy today."]], ["___ rainy today.", "It is", "It has", "Está chovendo hoje.", "Para o clima, use it is, não it has."]];
