content[212]=[[["Ben looks at a photo of the class.", "Ben olha uma foto da turma."], ["Ava is wearing a colorful blouse.", "A Ava está usando uma blusa colorida."], ["Noah is wearing a casual white shirt.", "O Noah está usando uma camisa branca informal."], ["Lia is wearing jeans and a red hat.", "A Lia está usando jeans e um chapéu vermelho."], ["Ben is laughing in the photo.", "Ben está rindo na foto."]], [["What are you wearing today?", "O que você está vestindo hoje?"], ["I am wearing black socks.", "Estou usando meias pretas."], ["Are they new?", "Elas são novas?"], ["Yes, I am wearing them for the first time.", "Sim, estou usando pela primeira vez."], ["What is Ava wearing?", "O que a Ava está vestindo?"], ["She is wearing a yellow blouse.", "Ela está usando uma blusa amarela."], ["So you are wearing black today?", "Então você está de preto hoje?"], ["Yes, and I am wearing jeans too.", "Sim, e estou de jeans também."]], ["Final -ing em wearing", "Termine com um n nasal suave, sem soltar o g: weari-ng.", ["wearing", "I am wearing a hat."]], ["I ___ a jacket today.", "am wearing", "wear", "Estou usando uma jaqueta hoje.", "Para o que acontece agora, use am + verbo com -ing."]];
