content[213]=[[["Peg stands at the door.", "Peg está parada na porta."], ["Lou asks if she is wearing a vest.", "O Lou pergunta se ela está usando um colete."], ["She is not wearing a vest today.", "Hoje ela não está usando colete."], ["Lou gives her his old vest.", "O Lou dá a ela o colete velho dele."], ["Peg is wearing the vest now.", "Agora a Peg está usando o colete."]], [["Are you wearing a scarf today?", "Você está de cachecol hoje?"], ["Yes, I am. It is cotton.", "Sim, estou. É de algodão."], ["Is Lou wearing earrings?", "O Lou está usando brincos?"], ["No, he is not. He has a ring.", "Não, não está. Ele tem um anel."], ["Are they wearing coats?", "Eles estão de casaco?"], ["Yes, they are. It is cold.", "Sim, estão. Está frio."], ["Is she wearing earrings?", "Ela está usando brincos?"], ["Yes, she is. They are red.", "Está, sim. São vermelhos."]], ["Respostas curtas fracas", "Em Yes, I am, o am é forte no fim; em No, he is not, destaque o not.", ["am", "Yes, I am."]], ["___ you wearing a vest?", "Are", "Do", "Você está usando um colete?", "A pergunta no present continuous começa com be: Are you wearing…?"]];
