content[214]=[[["Tina wants a new bag.", "Tina quer uma bolsa nova."], ["The store has a black bag and a purple bag.", "A loja tem uma bolsa preta e uma roxa."], ["Tina likes the color yellow.", "A Tina gosta da cor amarela."], ["A yellow bag is in the window.", "Uma bolsa amarela está na vitrine."], ["She pays twenty dollars and says thank you.", "Ela paga vinte dólares e agradece."]], [["What color is your bag?", "De que cor é a sua bolsa?"], ["It is a yellow bag.", "É uma bolsa amarela."], ["What color is the jacket?", "De que cor é a jaqueta?"], ["It is a dark blue jacket.", "É uma jaqueta azul-escura."], ["Do you like the pink hat?", "Você gosta do chapéu rosa?"], ["No, I like the white hat.", "Não, gosto do chapéu branco."], ["So you want a yellow bag?", "Então você quer uma bolsa amarela?"], ["Yes, I love the color.", "Sim, adoro a cor."]], ["/j/ em yellow", "Comece com um i bem rápido, quase um y: YEL-low, sem soltar um j como em “jogo”.", ["yellow", "I like the yellow bag."]], ["I have a ___.", "yellow bag", "bag yellow", "Eu tenho uma bolsa amarela.", "Em inglês a cor vem antes do substantivo."]];
