content[215]=[[["Ava tries on new jeans.", "Ava experimenta uma calça jeans nova."], ["They are too small for her.", "Elas ficam pequenas demais para ela."], ["They do not fit her at all.", "Elas não servem nela de jeito nenhum."], ["Then she tries a silk dress.", "Aí ela experimenta um vestido de seda."], ["The dress is too long for her.", "O vestido é comprido demais para ela."]], [["How are the jeans?", "Como ficou a calça?"], ["They are too tight.", "Estão apertadas demais."], ["Does it fit now?", "Agora serve?"], ["Not yet, it is too long.", "Ainda não, está comprido demais."], ["Is the dress too big?", "O vestido está grande demais?"], ["No, the dress is good.", "Não, o vestido está bom."], ["So the jeans are too small?", "Então a calça está pequena demais?"], ["Yes, I need a large size.", "Sim, preciso do tamanho grande."]], ["/t/ forte em too e tight", "Solte um t com um sopro de ar: too e tight começam com t aspirado.", ["too", "It is too small."]], ["These jeans are ___ small.", "too", "too much", "Esta calça é pequena demais.", "Too vem direto antes do adjetivo, sem much."]];
