content[216]=[[["Noah needs clothes for winter.", "O Noah precisa de roupas para o inverno."], ["His mother wants to go to the store.", "A mãe dele quer ir à loja."], ["Noah likes the blue sweatshirt.", "O Noah gosta do moletom azul."], ["He also wants an overcoat.", "Ele também quer um sobretudo."], ["They buy the sweatshirt and the overcoat.", "Eles compram o moletom e o sobretudo."]], [["Which clothes do you need today?", "Quais roupas você precisa hoje?"], ["I need a warm sweatshirt.", "Eu preciso de um moletom quente."], ["Do you want an overcoat too?", "Você quer um sobretudo também?"], ["Yes, I like the black overcoat.", "Quero, gosto do sobretudo preto."], ["What does Ben want?", "O que o Ben quer?"], ["He wants a coat in the new style.", "Ele quer um casaco no estilo novo."], ["Do you like this blue sweatshirt?", "Você gosta deste moletom azul?"], ["Yes, I like it, and I need it.", "Sim, gosto e preciso dele."]], ["/ʃ/ em sweatshirt", "Em sweatshirt, o sh soa como o x de “xícara”: sweat-shirt, com a língua recuada.", ["sweatshirt", "I need a sweatshirt."]], ["Noah ___ a new sweatshirt.", "needs", "need", "Noah precisa de um moletom novo.", "Com nomes no singular, o verbo leva -s: needs."]];
