content[217]=[[["Tina shows two gowns to Lou.", "A Tina mostra dois vestidos de festa ao Lou."], ["This one is blue, and the cloth is soft.", "Este é azul, e o tecido é macio."], ["That one is red, with a small ring.", "Aquele é vermelho, com um anelzinho."], ["Which one does Lou like?", "De qual o Lou gosta?"], ["He likes this one, so Tina buys it.", "Ele gosta desta, então a Tina compra."]], [["Which one do you like?", "De qual você gosta?"], ["I like this one with the soft cloth.", "Gosto deste, com o tecido macio."], ["Which one is yours?", "Qual é a sua?"], ["That one over there is mine.", "Aquela ali é a minha."], ["Which ring do you want?", "Qual anel você quer?"], ["I want that small ring.", "Quero aquele anel pequeno."], ["So this one is for Tina?", "Então esta é para a Tina?"], ["Yes, and that one is for Lou.", "Sim, e aquela é para o Lou."]], ["/θ/ e /ð/ em this e that", "Em this e that, a ponta da língua toca os dentes e a voz vibra: não diga dis nem dat.", ["this", "This one is mine."]], ["___ one do you want?", "Which", "What", "Qual você quer?", "Para escolher entre opções, use which."]];
