content[218]=[[["Peg looks out the window.", "Peg olha pela janela."], ["There is frost on the window today.", "Hoje há geada na janela."], ["Ben says, Take your skates.", "O Ben diz: leve os seus patins."], ["He also says, Wear a coat.", "Ele também diz: vista um casaco."], ["Peg takes both and goes out.", "Peg leva os dois e sai."]], [["What is the weather like?", "Como está o tempo?"], ["It is cold. Wear a coat.", "Está frio. Vista um casaco."], ["Is there frost on the lake?", "Tem geada no lago?"], ["Yes, take your skates.", "Tem, sim. Leve os seus patins."], ["Should I wear a hat?", "Devo usar chapéu?"], ["Yes, wear a hat and a scarf.", "Sim, use chapéu e cachecol."], ["So I take my coat and skates?", "Então levo o casaco e os patins?"], ["Yes, and close the door.", "Sim, e feche a porta."]], ["/sk/ em skates", "Comece com s e k juntos, sem vogal antes: skates, não “eskates”.", ["skates", "Take your skates."]], ["___ your skates today.", "Take", "You take", "Leve os seus patins hoje.", "No conselho, comece com o verbo base, sem you."]];
