content[219]=[[["Ava looks at the sky.", "Ava olha para o céu."], ["There is a thunderstorm over the park.", "Há uma tempestade com trovões sobre o parque."], ["It is windy and cold.", "Está ventando e frio."], ["It is not mild, but it is humid.", "Não está ameno, mas está úmido."], ["Ava takes a coat and goes out.", "Ava pega um casaco e sai."]], [["Is it windy today?", "Está ventando hoje?"], ["Yes, it is very windy.", "Sim, está ventando muito."], ["Is there a thunderstorm today?", "Vai ter tempestade hoje?"], ["Yes, there is one at four.", "Vai, sim, às quatro."], ["What are you wearing?", "O que você está vestindo?"], ["I am wearing a coat and a hat.", "Estou de casaco e chapéu."], ["So we need an umbrella?", "Então precisamos de um guarda-chuva?"], ["Yes, take it and let us go.", "Sim, leve e vamos."]], ["/k/ em cloud", "Feche a garganta com o fundo da língua e solte com um sopro: cloud começa com k forte.", ["cloud", "There is a cloud."]], ["It is ___ today.", "windy", "wind", "Hoje está ventando.", "Depois de it is, use o adjetivo windy, não o substantivo wind."]];
