content[220]=[[["Lia meets her new neighbor, Ravi.", "Lia conhece seu novo vizinho, Ravi."], ["She asks, \"What do you do?\"", "Ela pergunta: \"O que você faz?\""], ["Ravi says, \"I am a salesman.\"", "Ravi diz: “Sou vendedor.”"], ["His brother is a lawyer.", "O irmão dele é advogado."], ["Lia is a student, so she smiles.", "Lia é estudante, então ela sorri."]], [["What do you do?", "O que você faz da vida?"], ["I am a salesman at the port.", "Sou vendedor no porto."], ["That is a hard job, right?", "É um trabalho difícil, não é?"], ["Yes, but I like it a lot.", "Sim, mas eu gosto muito."], ["Is your friend a salesman too?", "Seu amigo também é vendedor?"], ["No, she is an assistant.", "Não, ela é assistente."], ["What do you do, Lia?", "E você, Lia, o que faz?"], ["I am a student. I study English.", "Sou estudante. Estudo inglês."]], ["Acento em salesman", "Em salesman, a primeira sílaba é a forte: SALES-man, e o man final é fraco.", ["salesman", "I am a salesman."]], ["I am ___ salesman.", "a", "an", "Eu sou vendedor.", "Antes de som de consoante, use a; salesman começa com som de consoante."]];
