content[221]=[[["Noah works in a bookshop downtown.", "O Noah trabalha em uma livraria no centro."], ["His sister Tina works at a department store.", "A irmã dele, a Tina, trabalha em uma loja de departamentos."], ["She works with money all day.", "Ela trabalha com dinheiro o dia todo."], ["Their friend Peg works at a laboratory.", "A amiga deles, a Peg, trabalha em um laboratório."], ["They meet at a bar on Fridays.", "Eles se encontram em um bar às sextas."]], [["Where does Noah work?", "Onde o Noah trabalha?"], ["He works in a bookshop.", "Ele trabalha em uma livraria."], ["And where does Tina work?", "E onde a Tina trabalha?"], ["She works at a department store.", "Ela trabalha em uma loja de departamentos."], ["Where does Peg work?", "Onde a Peg trabalha?"], ["She works at a laboratory near the river.", "Ela trabalha em um laboratório perto do rio."], ["Where do you work, Lia?", "Onde você trabalha, Lia?"], ["I work at a small bakery.", "Trabalho em uma padaria pequena."]], ["S final em works", "Em works, o s no fim soa como /s/ e não como z; solte o ar devagar.", ["works", "She works here."]], ["She ___ at a school.", "works", "work", "Ela trabalha em uma escola.", "Com he ou she, o verbo no presente leva -s."]];
