content[222]=[[["Ben can drive, but he cannot bake.", "O Ben sabe dirigir, mas não sabe assar."], ["He wants to bake a cake for Ava.", "Ele quer assar um bolo para a Ava."], ["Ava can bake very well.", "A Ava assa muito bem."], ["She helps him in the kitchen.", "Ela ajuda ele na cozinha."], ["Ben is slow, but he is happy.", "Ben é lento, mas está feliz."]], [["Can you bake, Ben?", "Você sabe assar, Ben?"], ["No, I cannot bake.", "Não, não sei assar."], ["Can you drive a car?", "Você sabe dirigir?"], ["Yes, I can drive very well.", "Sim, dirijo muito bem."], ["Can Ava sew?", "A Ava sabe costurar?"], ["Yes, she can sew and knit.", "Sabe, sim. Ela costura e tricota."], ["Can she help me on Sunday?", "Ela pode me ajudar no domingo?"], ["Yes, she can come at ten.", "Sim, ela pode vir às dez."]], ["Can e cannot", "Em can, a vogal é fraca (/kən/); em cannot, o acento cai na segunda sílaba: can-NOT.", ["cannot", "I cannot swim."]], ["I ___ bake.", "cannot", "no can", "Eu não sei assar.", "A negação de can é cannot, nunca no can."]];
