content[223]=[[["On Saturday, Ravi has a party at the lake.", "No sábado, o Ravi faz uma festa no lago."], ["He enjoys cooking with his friends.", "Ele curte cozinhar com os amigos."], ["Lia loves painting, so she brings paper.", "Lia adora pintar, então leva papel."], ["Ben likes cycling around the lake.", "O Ben gosta de pedalar em volta do lago."], ["Everyone is happy, and the food is great.", "Todos estão felizes, e a comida está ótima."]], [["What do you enjoy doing on Saturday?", "O que você curte fazer no sábado?"], ["I enjoy cooking for my friends.", "Curto cozinhar para meus amigos."], ["Do you like cycling?", "Você gosta de pedalar?"], ["Yes, I love cycling.", "Gosto, sim. Adoro pedalar."], ["Do you like sailing too?", "Você gosta de velejar também?"], ["No, I like listening to music.", "Não, gosto de ouvir música."], ["Do you enjoy painting, Lia?", "Você curte pintar, Lia?"], ["Yes, I love painting with Ravi.", "Sim, adoro pintar com o Ravi."]], ["Terminação -ing", "Em cooking e painting, o ing é curto: língua alta, sem pronunciar um g forte no fim.", ["cooking", "I enjoy cooking."]], ["I enjoy ___ dinner.", "cooking", "to cook", "Eu curto cozinhar o jantar.", "Depois de enjoy, o verbo vai com -ing."]];
