content[224]=[[["Lia has math on Monday at nine.", "Lia tem matemática na segunda às nove."], ["Science is on Tuesday at ten.", "Ciências é na terça às dez."], ["On Wednesday, she has history at eleven.", "Na quarta, ela tem história às onze."], ["Her friend Ben has art on Friday.", "O amigo dela, Ben, tem artes na sexta."], ["They eat lunch at noon every day.", "Eles almoçam ao meio-dia todo dia."]], [["When is your math class?", "Quando é sua aula de matemática?"], ["It is on Monday at nine.", "É na segunda, às nove."], ["What time is science?", "A que horas é ciências?"], ["Science is at ten on Tuesday.", "Ciências é às dez na terça."], ["Is history on Wednesday?", "História é na quarta?"], ["Yes, it is at eleven.", "Sim, é às onze."], ["When is art class?", "Quando é a aula de artes?"], ["Art is on Friday at two.", "Artes é na sexta, às duas."]], ["TH em math", "Ponha a ponta da língua entre os dentes e solte o ar para o th final de math.", ["math", "I like math."]], ["Math is ___ Monday.", "on", "at", "A matemática é na segunda.", "Use on com dias da semana e at com horas."]];
