content[225]=[[["Ava has a lot to do after school.", "A Ava tem muita coisa para fazer depois da escola."], ["She has to put away the plates first.", "Primeiro ela tem que guardar os pratos."], ["Her brother Nico has to wash the dishes.", "O irmão dela, Nico, tem que lavar a louça."], ["Mom says, \"You both have to work first.\"", "A mãe diz: \"Vocês dois têm que trabalhar primeiro.\""], ["Then they can play outside.", "Depois eles podem brincar lá fora."]], [["Do you have to work today?", "Você tem que trabalhar hoje?"], ["Yes, I have to work at five.", "Sim, tenho que trabalhar às cinco."], ["What does Ava have to do?", "O que a Ava tem que fazer?"], ["She has to do the ironing.", "Ela tem que passar a roupa."], ["Do you have to wash the dishes?", "Você tem que lavar a louça?"], ["Yes, I have to wash them now.", "Sim, tenho que lavá-la agora."], ["Do you have to mow the grass?", "Você tem que cortar a grama?"], ["No, I do not have to mow it.", "Não, eu não tenho que cortar."]], ["Has to", "Em has to, o s soa como /s/ e o to fica fraco: HAS-tə.", ["dishes", "I have to wash the dishes."]], ["Ava ___ do the ironing.", "has to", "have to", "Ava tem que passar a roupa.", "Com he ou she, use has to."]];
