content[226]=[[["The market starts at seven in the morning.", "O mercado abre às sete da manhã."], ["It finishes at a quarter to four.", "Ele fecha às quatro menos quinze."], ["Ravi works from eight to half past one.", "O Ravi trabalha lá das oito até uma e meia."], ["Tina works from two to four.", "Tina trabalha das duas às quatro."], ["Many people come to the market daily.", "Muita gente vem ao mercado todo dia."]], [["What time does the market start?", "A que horas o mercado começa?"], ["It starts at seven.", "Começa às sete."], ["When does it finish?", "Quando ele termina?"], ["It finishes at a quarter to four.", "Fecha às quatro menos quinze."], ["Do you work all day?", "Você trabalha o dia todo?"], ["No, I work from eight to half past one.", "Não, trabalho das oito à uma e meia."], ["Who works after that?", "Quem trabalha depois disso?"], ["Tina does. She works from two to four.", "A Tina. Ela trabalha das duas às quatro."]], ["Final de finish", "Em finish, o final -sh é um chiado longo, com os lábios um pouco arredondados.", ["finish", "I finish at four."]], ["The market starts ___ seven.", "at", "in", "O mercado abre às sete.", "Use at com a hora exata."]];
