content[227]=[[["Ben is late for work today.", "Ben está atrasado para o trabalho hoje."], ["Lou asks, \"Why are you late?\"", "Lou pergunta: \"Por que você está atrasado?\""], ["Ben says, \"I am late because there is an accident.\"", "Ben diz: “Estou atrasado porque há um acidente.”"], ["Lou says, \"That is OK. You are here now.\"", "Lou diz: \"Tudo bem. Você está aqui agora.\""], ["Ben is tired, but he is happy to work.", "Ben está cansado, mas feliz por trabalhar."]], [["Why are you tired?", "Por que você está cansado?"], ["Because I have a new job.", "Porque tenho um emprego novo."], ["Why do you work so early?", "Por que você trabalha tão cedo?"], ["Because the shop opens at six.", "Porque a loja abre às seis."], ["Why are you not eating?", "Por que você não está comendo?"], ["Because I have a stomachache.", "Porque estou com dor de barriga."], ["Why do you like the job?", "Por que você gosta do trabalho?"], ["Because my friends are there.", "Porque meus amigos estão lá."]], ["Som de WH em why", "Arredonde os lábios como em u e abra rápido para o ai de why.", ["why", "Why are you late?"]], ["I am late ___ the train is slow.", "because", "why", "Estou atrasado porque o trem está lento.", "Para dar o motivo, use because; why serve para perguntar."]];
