content[228]=[[["Lia is at a busy restaurant.", "Lia está em um restaurante movimentado."], ["She sees a young waitress near the door.", "Ela vê uma garçonete jovem perto da porta."], ["Ben says the waitress works there every day.", "O Ben diz que a garçonete trabalha lá todo dia."], ["Peg works in the kitchen with her.", "A Peg trabalha na cozinha com ela."], ["They both smile at Lia.", "Os dois sorriem para a Lia."]], [["Does Nico work here?", "O Nico trabalha aqui?"], ["Yes, he does.", "Sim, trabalha."], ["Does he work in the kitchen?", "Ele trabalha na cozinha?"], ["No, he does not. He is a guard.", "Não, não trabalha. Ele é segurança."], ["Do you work on Sunday?", "Você trabalha no domingo?"], ["Yes, I do, every Sunday.", "Sim, todo domingo."], ["Does the director work with you?", "A diretora trabalha com você?"], ["Yes, she does.", "Sim, trabalha."]], ["Does", "Em does, o d inicial é firme e a vogal é curta: dəz.", ["does", "Does she work here?"]], ["___ Nico work here?", "Does", "Do", "O Nico trabalha aqui?", "Com he, she ou um nome, a pergunta começa com Does."]];
