content[231]=[[["Peg needs to go to the museum.", "Peg precisa ir ao museu."], ["A taxi is more expensive than the subway.", "Um táxi é mais caro que o metrô."], ["But the subway is more crowded than a taxi.", "Mas o metrô é mais lotado que um táxi."], ["The subway is more convenient for Peg.", "O metrô é mais prático para a Peg."], ["She takes the subway today.", "Ela pega o metrô hoje."]], [["Is the subway more crowded than the bus?", "O metrô é mais lotado que o ônibus?"], ["Yes, it is more crowded in the morning.", "Sim, é mais lotado de manhã."], ["Is a taxi more expensive?", "Um táxi é mais caro?"], ["Yes, it is more expensive than both.", "Sim, é mais caro que os dois."], ["Which one is more relaxing?", "Qual é mais relaxante?"], ["The taxi is more relaxing.", "O táxi é mais relaxante."], ["Is the bus more interesting than the subway?", "O ônibus é mais interessante que o metrô?"], ["Yes, because you can see the city.", "Sim, porque dá para ver a cidade."]], ["Acento em expensive", "Em expensive, a força cai na segunda sílaba: ex-PEN-sive.", ["expensive", "It is more expensive."]], ["The subway is ___ than the bus.", "more crowded", "crowded", "O metrô é mais lotado que o ônibus.", "Adjetivo longo usa more antes dele; sem more, a comparação fica incompleta."]];
