content[232]=[[["Lia is lost in a big city.", "Lia está perdida em uma cidade grande."], ["She asks, \"How do I get to the theatre?\"", "Ela pergunta: \"Como chego ao teatro?\""], ["A woman says, \"Go straight, then turn left at the traffic light.\"", "Uma mulher diz: \"Siga em frente e vire à esquerda no semáforo.\""], ["Then Lia walks two blocks.", "Depois Lia anda dois quarteirões."], ["Then Lia walks along a wide avenue.", "Depois Lia anda por uma avenida larga."]], [["Excuse me, how do I get to the theatre?", "Com licença, como chego ao teatro?"], ["First, go straight along the avenue.", "Primeiro, siga em frente pela avenida."], ["And then?", "E depois?"], ["Then turn left at the traffic light.", "Depois vire à esquerda no semáforo."], ["Is it far from there?", "Fica longe de lá?"], ["No, it is on the right.", "Não, fica à direita."], ["So I go straight, then turn left?", "Então sigo em frente e viro à esquerda?"], ["Yes, that is right.", "Sim, isso mesmo."]], ["Ritmo de How do I", "Em how do I get to, as palavras pequenas ficam fracas e get e to se ligam: get-tə.", ["theatre", "How do I get to the theatre?"]], ["___ do I get to the theatre?", "How", "What", "Como eu chego ao teatro?", "Para pedir o caminho, use How do I get to…?"]];
patterns[232]=new RegExp("how do i get to|\\bthen\\b","i");
