content[236]=[[["A postman gives directions to Noah.", "Um carteiro dá direções ao Noah."], ["\"Take the second street on the right,\" he says.", "\"Pegue a segunda rua à direita\", diz ele."], ["\"Then turn left at the corner.\"", "\"Depois vire à esquerda na esquina.\""], ["\"The college is on the fourth street.\"", "\"A faculdade fica na quarta rua.\""], ["Noah says thanks and walks on.", "Noah agradece e segue em frente."]], [["How do I get to the college?", "Como eu chego à faculdade?"], ["Take the second street on the right.", "Pegue a segunda rua à direita."], ["Then do I turn left?", "Depois eu viro à esquerda?"], ["Yes, turn left on the third street.", "Sim, vire à esquerda na terceira rua."], ["Which street is the college on?", "Em qual rua fica a faculdade?"], ["It is on the fourth street, on the left.", "Fica na quarta rua, à esquerda."], ["So I turn right, then left?", "Então eu viro à direita e depois à esquerda?"], ["Yes, you are right.", "Sim, você está certo."]], ["TH em third", "Ponha a língua entre os dentes para o th e depois puxe o r americano: THURD.", ["third", "The third street."]], ["Take the ___ street on the left.", "second", "two", "Pegue a segunda rua à esquerda.", "Para indicar a ordem, use o ordinal: second, third."]];
