content[239]=[[["Lia visits a famous city today.", "Lia visita uma cidade famosa hoje."], ["The university is more exciting than the museum.", "A universidade é mais animada que o museu."], ["Lia asks, \"Which bus goes to the university?\"", "Lia pergunta: \"Qual ônibus vai à universidade?\""], ["\"The blue bus goes there,\" says Peg.", "\"O ônibus azul vai para lá\", diz a Peg."], ["The walk is tiring, so Lia takes the bus.", "A caminhada é cansativa, então Lia pega o ônibus."]], [["Is the university far from here?", "A universidade fica longe daqui?"], ["It is only two miles from here.", "Fica só a duas milhas daqui."], ["Which bus goes there?", "Qual ônibus vai para lá?"], ["The blue bus goes there.", "O ônibus azul vai para lá."], ["Is walking more tiring than the bus?", "Andar é mais cansativo que o ônibus?"], ["Yes, it is much more tiring.", "Sim, é muito mais cansativo."], ["How long does it take by bus?", "Quanto tempo leva de ônibus?"], ["It takes about twenty minutes.", "Leva cerca de vinte minutos."]], ["Som /ɪ/ em city", "Em city, o i é curto e o t soa quase como um d rápido: SID-i.", ["city", "The city is big."]], ["The bus is ___ than the train.", "slower", "more slow", "O ônibus é mais lento que o trem.", "Adjetivo curto recebe -er antes de than."]];
