content[241]=[[["Ava has a headache this morning.", "Ava está com dor de cabeça esta manhã."], ["Her brother has the flu.", "O irmão dela está com gripe."], ["He has a cough and a sore throat.", "Ele tem tosse e dor de garganta."], ["Their mother takes his temperature.", "A mãe deles mede a temperatura dele."], ["His ear hurts, so he stays in bed.", "O ouvido dele dói, então ele fica na cama."]], [["Do you have the flu, Noah?", "Você está com gripe, Noah?"], ["Yes, I have the flu.", "Sim, estou com gripe."], ["Do you have a headache too?", "Você também está com dor de cabeça?"], ["No, but I have a backache.", "Não, mas estou com dor nas costas."], ["Does your throat hurt?", "Sua garganta dói?"], ["Yes, it hurts when I talk.", "Sim, dói quando eu falo."], ["So you have the flu and a backache?", "Então você tem gripe e dor nas costas?"], ["Yes, and I stay home today.", "Sim, e hoje fico em casa."]], ["O th em throat", "Ponha a ponta da língua entre os dentes e sopre, depois faça o r.", ["throat", "My throat hurts."]], ["Ava ___ a headache.", "has", "have", "Ava está com dor de cabeça.", "Com she/he/Ava, usamos has, não have."]];
