content[242]=[[["Peg feels ill after lunch.", "A Peg se sente doente depois do almoço."], ["She feels awful and cold.", "Ela se sente péssima e com frio."], ["Tina is worried about her.", "A Tina está preocupada com ela."], ["Peg drinks tea and sleeps.", "A Peg toma chá e dorme."], ["In the morning, she feels better.", "De manhã, ela se sente melhor."]], [["How do you feel, Peg?", "Como você está se sentindo, Peg?"], ["I feel ill and tired.", "Eu me sinto doente e cansada."], ["Do you feel cold?", "Você está com frio?"], ["Yes, a little. Is the window open?", "Sim, um pouco. A janela está aberta?"], ["No, it is closed.", "Não, está fechada."], ["Then I feel ill, not cold.", "Então eu me sinto doente, não com frio."], ["How do you feel now?", "Como você se sente agora?"], ["I feel better, thank you.", "Eu me sinto melhor, obrigada."]], ["O i curto em ill", "Diga i com a boca relaxada, mais curto que o ee de feel.", ["ill", "I feel ill."]], ["I ___ better today.", "feel", "am feel", "Eu me sinto melhor hoje.", "Depois de I usamos feel direto, sem am."]];
