content[243]=[[["Lou has a bad cough.", "O Lou está com uma tosse forte."], ["Ravi says, You need to rest.", "O Ravi diz: Você precisa descansar."], ["Lou needs to take a warm bath.", "O Lou precisa tomar um banho quente."], ["Work is very stressful for him.", "O trabalho é muito estressante para ele."], ["Lou needs to sit by the chimney.", "O Lou precisa sentar perto da chaminé."]], [["You look tired, Lou.", "Você parece cansado, Lou."], ["I am. I need to sleep.", "Estou. Eu preciso dormir."], ["Do you need to work today?", "Você precisa trabalhar hoje?"], ["No, I need to stay home.", "Não, preciso ficar em casa."], ["You need to take a bath.", "Você precisa tomar um banho."], ["Good idea. Is the water warm?", "Boa ideia. A água está quente?"], ["Yes, and you need to sleep after.", "Sim, e você precisa dormir depois."], ["I will. Thank you, Ravi.", "Eu vou. Obrigado, Ravi."]], ["Reduzir need to", "Na fala rápida, to soa fraco: need-ta.", ["need to", "You need to sleep."]], ["You ___ sleep.", "need to", "need", "Você precisa dormir.", "Depois de need, o outro verbo vem com to."]];
