content[245]=[[["June calls the medical center at nine.", "A June liga para o centro médico às nove."], ["She wants to see a doctor.", "Ela quer ver um médico."], ["The woman says, Come at ten.", "A mulher diz: venha às dez."], ["June makes an appointment for Monday.", "June marca uma consulta para segunda."], ["She wants to stay healthy.", "Ela quer se manter saudável."]], [["I want to make an appointment.", "Quero marcar uma consulta."], ["Do you want a doctor on Monday?", "Você quer um médico na segunda?"], ["A doctor, please.", "Um médico, por favor."], ["We have an hour at ten.", "Temos um horário às dez."], ["Is there a time at noon?", "Tem um horário ao meio-dia?"], ["Yes, there is one at noon.", "Sim, tem um ao meio-dia."], ["So I come at noon on Monday?", "Então eu venho ao meio-dia na segunda?"], ["Yes, see you at noon.", "Sim, até lá ao meio-dia."]], ["Linking: an appointment", "Ligue o n de an à vogal seguinte: a-nappointment.", ["an hour", "I have an hour at ten."]], ["I want ___ appointment at ten.", "an", "a", "Quero uma consulta às dez.", "Appointment começa com som de vogal, então usamos an."]];
