content[246]=[[["Tina has a rash on her arm.", "A Tina tem uma irritação no braço."], ["She goes to see a nurse.", "Ela vai ver uma enfermeira."], ["The nurse asks, How long does it last?", "A enfermeira pergunta: Quanto tempo dura?"], ["It lasts for a week.", "Dura uma semana."], ["The nurse gives her some cream.", "A enfermeira dá a ela uma pomada."]], [["How long does your rash last?", "Quanto tempo sua irritação dura?"], ["It lasts for three days.", "Dura por três dias."], ["How long does the headache last?", "Quanto tempo a dor de cabeça dura?"], ["Only for one day.", "Só por um dia."], ["Does it itch at night?", "Coça à noite?"], ["Yes, for two nights now.", "Sim, faz duas noites."], ["So the rash lasts three days?", "Então a irritação dura três dias?"], ["Yes, for three days.", "Sim, por três dias."]], ["O ee em week", "Alongue o i e termine com k: wiiik, bem diferente do i curto de sick.", ["week", "I wait a week."]], ["How ___ does the cough last?", "long", "much", "Quanto tempo a tosse dura?", "How long pergunta a duração, e a resposta usa for."]];
