content[247]=[[["Noah feels weak and tired.", "O Noah se sente fraco e cansado."], ["His aunt says, You should eat squash.", "A tia dele diz: Você deve comer abóbora."], ["He should eat bean soup, too.", "Ele deve comer sopa de feijão também."], ["He should not eat rich food tonight.", "Ele não deve comer comida pesada hoje à noite."], ["Noah feels better after dinner.", "O Noah se sente melhor depois do jantar."]], [["What should I eat today?", "O que eu devo comer hoje?"], ["You should eat squash and rice.", "Você deve comer abóbora e arroz."], ["Should I eat bean soup too?", "Devo comer sopa de feijão também?"], ["Yes, you should eat bean soup.", "Sim, você deve comer sopa de feijão."], ["Should I eat rich food?", "Devo comer comida pesada?"], ["No, you should not eat rich food.", "Não, você não deve comer comida pesada."], ["So I should eat squash and beans?", "Então devo comer abóbora e feijão?"], ["Yes, and you should rest.", "Sim, e você deve descansar."]], ["Acento em should", "O l é mudo: diga chud, rimando com good.", ["should", "You should eat squash."]], ["You ___ drink water.", "should", "should to", "Você deve beber água.", "Should vem direto antes do verbo, sem to."]];
