content[248]=[[["Ben falls at the park.", "Ben cai no parque."], ["Ava runs to him.", "Ava corre até ele."], ["She asks, What is the matter?", "Ela pergunta: Qual é o problema?"], ["His wrist and finger hurt.", "O pulso e o dedo dele doem."], ["Ava calls a nurse for help.", "Ava chama uma enfermeira para ajudar."]], [["What is the matter, Ben?", "Qual é o problema, Ben?"], ["My finger hurts after the fall.", "Meu dedo dói depois da queda."], ["Where does it hurt?", "Onde dói?"], ["Here, near my wrist.", "Aqui, perto do pulso."], ["Does your finger hurt too?", "Seu dedo também dói?"], ["Yes, a lot, when I walk.", "Sim, muito, quando eu ando."], ["So the matter is your wrist and finger?", "Então o problema é o pulso e o dedo?"], ["Yes. Please call the nurse.", "Sim. Por favor, chame a enfermeira."]], ["Acento em matter", "Dê força à primeira sílaba: MAT-er, com o t suave.", ["matter", "What is the matter?"]], ["Where ___ it hurt?", "does", "do", "Onde dói?", "Com it usamos does nas perguntas."]];
