content[249]=[[["Lou has a sore thumb.", "O Lou está com o polegar dolorido."], ["He goes to the drugstore near home.", "Ele vai à farmácia perto de casa."], ["The nurse gives him some cream.", "A enfermeira dá a ele uma pomada."], ["She says, Keep your nails short, too.", "Ela diz: Mantenha as unhas curtas também."], ["Lou does less housework and feels better.", "O Lou faz menos tarefas domésticas e melhora."]], [["Hello. My thumb hurts a lot.", "Olá. Meu polegar dói muito."], ["You need some cream. Take this one.", "Você precisa de pomada. Leve esta."], ["Do I need a bandage too?", "Eu preciso de curativo também?"], ["Yes, take a bandage for the thumb.", "Sim, leve um curativo para o polegar."], ["How long should I use the cream?", "Por quanto tempo devo usar a pomada?"], ["Use it for five days.", "Use por cinco dias."], ["So I use cream for five days?", "Então uso a pomada por cinco dias?"], ["Yes. If it still hurts, see a doctor.", "Sim. Se ainda doer, procure um médico."]], ["Acento em drugstore", "Força na primeira sílaba: DRAG-stor, com o r americano no fim.", ["drugstore", "The drugstore is near here."]], ["You ___ use the cream for five days.", "should", "should to", "Você deve usar a pomada por cinco dias.", "Should vem direto antes do verbo, sem to."]];
