content[254]=[[["Noah gets a message from Peg.", "Noah recebe uma mensagem de Peg."], ["She wants to play basketball today.", "Ela quer jogar basquete hoje."], ["Noah is tired after a long day.", "Noah está cansado depois de um longo dia."], ["Sorry, I cannot play today.", "Desculpe, não posso jogar hoje."], ["Maybe we can play on Sunday.", "Talvez possamos jogar no domingo."]], [["Do you want to play today?", "Você quer jogar hoje?"], ["Sorry, I cannot. I am tired.", "Desculpe, não posso. Estou cansado."], ["Are you sick or just tired?", "Você está doente ou só cansado?"], ["Just tired. I have a quiz on Monday.", "Só cansado. Tenho uma prova rápida na segunda."], ["Can you come at six?", "Você pode vir às seis?"], ["Sorry, I cannot come at six.", "Desculpe, não posso ir às seis."], ["Maybe on Sunday, then?", "Talvez no domingo, então?"], ["Yes, I can on Sunday.", "Sim, no domingo eu posso."]], ["Cannot em uma palavra", "Diga CAN-not com força na primeira sílaba; cannot é uma palavra só.", ["cannot", "I cannot come today."]], ["Sorry, I ___ come today.", "cannot", "not can", "Desculpe, não posso ir hoje.", "A negativa de can é cannot (can not não existe nessa ordem)."]];
