content[259]=[[["Peg has a busy Saturday.", "A Peg tem um sábado cheio."], ["She plays tennis in the morning.", "Ela joga tênis de manhã."], ["At noon, she eats lunch with the guys.", "Ao meio-dia, ela almoça com o pessoal."], ["At night, they watch movies together.", "À noite, eles assistem a filmes juntos."], ["On Sundays, Peg sends messages to the team.", "Aos domingos, a Peg manda mensagens para o time."]], [["What are you doing on Saturday?", "O que você vai fazer no sábado?"], ["I play tennis in the morning.", "Jogo tênis de manhã."], ["Do you want to have lunch?", "Você quer almoçar?"], ["Sure. Where do we eat?", "Claro. Onde a gente come?"], ["We eat with the guys at noon.", "Comemos com o pessoal ao meio-dia."], ["Do you want to watch movies tonight?", "Quer assistir a filmes hoje à noite?"], ["No, I cannot today. I am busy.", "Hoje não posso. Estou ocupada."], ["Maybe on Sunday, with the team.", "Talvez no domingo, com o time."]], ["Ritmo em frases de convite", "Suba a voz no fim de Do you want to...? e abaixe na resposta.", ["lunch", "Do you want to have lunch?"]], ["Peg ___ tennis on Saturday.", "plays", "go", "A Peg joga tênis no sábado.", "Com she/he/it, o verbo no presente leva -s."]];
patterns[259]=new RegExp("\\bon Saturday\\b|\\bplays?\\b|\\bdo you want to\\b|\\bwith\\b","i");
themes[259]="park";
photos[259]=["photo-parkPath-1.webp", "photo-lake-1.webp"];
stories[259]=["O sábado cheio de Peg", "Peg has a busy Saturday plan.~A Peg tem um plano de sábado bem cheio.|In the morning, she plays tennis twice.~De manhã, ela joga tênis duas vezes.|Her friend Ben asks, Do you want to watch movies?~O amigo Ben pergunta: Quer assistir a filmes?|Peg says, Sorry, I cannot. I am busy.~A Peg diz: Desculpe, não posso. Estou ocupada.|She is good at tennis, but not very good at football.~Ela é boa de tênis, mas não muito boa de futebol.|At noon, she eats lunch with the guys.~Ao meio-dia, ela almoça com o pessoal.|They are sitting together in the garden.~Eles estão sentados juntos no jardim.|Ben comes and says, Maybe now, then?~O Ben chega e diz: Talvez agora, então?|Peg likes movies once a week, so she says yes.~A Peg gosta de filmes uma vez por semana, então diz sim.|Now the whole team is watching a movie.~Agora o time inteiro está assistindo a um filme."];
plans[260]={"title": "A festa de ontem à noite", "file": "photo-friends-1.webp", "grammar": "Was e were em frases afirmativas", "goal": "Use was com I, he, she, it e were com you, we, they para falar de onde e como alguém estava no passado.", "words": [["pal", "parceiro"], ["ladies", "senhoras"], ["coke", "refrigerante"], ["sweetheart", "amor"]]};
content[260]=[[["Ben was at a big party last night.", "O Ben estava numa festa grande ontem à noite."], ["The tables were full and the lights were low.", "As mesas estavam cheias e as luzes estavam baixas."], ["Lia and the ladies were there too.", "A Lia e as senhoras também estavam lá."], ["The waiter was funny, but Ben was tired.", "O garçom era engraçado, mas o Ben estava cansado."], ["Ben and his pal Ava were home at midnight.", "O Ben e a parceira Ava estavam em casa à meia-noite."]], [["Where were you last night?", "Onde você estava ontem à noite?"], ["I was at a party.", "Eu estava numa festa."], ["Who was there with you?", "Quem estava lá com você?"], ["Lia and my pal Ava were there.", "A Lia e minha parceira Ava estavam lá."], ["How was the coke?", "Como estava o refrigerante?"], ["It was very good.", "Estava muito bom."], ["Why are you tired today?", "Por que você está cansado hoje?"], ["I was at the party until midnight.", "Fiquei na festa até a meia-noite."]], ["O som /w/ em was e were", "Arredonde bem os lábios, como em “u”, e abra para a vogal. Não diga “vós”.", ["was", "I was at home."]], ["We ___ at the party.", "were", "was", "Nós estávamos na festa.", "Com we usamos were, não was."]];
