content[261]=[[["Nico and Peg were at the movie.", "Nico e Peg estavam no filme."], ["The movie was about a prince and a princess.", "O filme era sobre um príncipe e uma princesa."], ["Nico was near the door.", "Nico estava perto da porta."], ["Two kings were funny and the end was sad.", "Dois reis eram engraçados e o final foi triste."], ["Peg was happy after the movie.", "Peg estava feliz depois do filme."]], [["Was the movie good?", "O filme foi bom?"], ["Yes, it was. It was funny.", "Sim, foi. Foi engraçado."], ["Were your seats good?", "Seus assentos eram bons?"], ["No, they were not.", "Não, não eram."], ["Was Nico with you?", "O Nico estava com você?"], ["Yes, he was.", "Sim, estava."], ["Were you home before ten?", "Você estava em casa antes das dez?"], ["Yes, I was. Nico was home too.", "Sim. O Nico também estava em casa."]], ["Entonação da pergunta com Was/Were", "Em perguntas sim/não a voz sobe no final: Was it good? ↗", ["was", "Was it good?"]], ["___ the seats near the door?", "Were", "Was", "Os assentos eram perto da porta?", "Seats é plural, então usamos Were."]];
