content[262]=[[["Lou was at the lake yesterday.", "Lou estava no lago ontem."], ["The weather was warm and sunny.", "O tempo estava quente e ensolarado."], ["Last week it was cold and rainy.", "Na semana passada estava frio e chuvoso."], ["Yesterday morning the lake was quiet.", "Ontem de manhã o lago estava quieto."], ["Lou was alone, but he was happy.", "Lou estava sozinho, mas estava feliz."]], [["When was your trip?", "Quando foi a sua viagem?"], ["It was last week.", "Foi na semana passada."], ["Was it long?", "Foi longa?"], ["No, it was only two days.", "Não, foram só dois dias."], ["Where were you yesterday?", "Onde você estava ontem?"], ["I was at the lake.", "Eu estava no lago."], ["Were you there last night too?", "Você também estava lá ontem à noite?"], ["No, I was home last night.", "Não, eu estava em casa ontem à noite."]], ["Acento em yesterday", "A força fica na primeira sílaba: YES-ter-day.", ["yesterday", "I was home yesterday."]], ["I was at home ___.", "yesterday", "tomorrow", "Eu estava em casa ontem.", "Com was usamos yesterday; tomorrow é futuro."]];
