content[265]=[[["Ravi went to the market with June.", "Ravi foi ao mercado com a June."], ["They saw many fruits and fish.", "Eles viram muitas frutas e peixes."], ["June had two pairs of red socks.", "June tinha dois pares de meias vermelhas."], ["They ate melons at a little table.", "Eles comeram melões numa mesinha."], ["They went home at noon.", "Eles foram para casa ao meio-dia."]], [["Who went to the market?", "Quem foi ao mercado?"], ["Ravi and June went.", "O Ravi e a June foram."], ["Who saw the fish?", "Quem viu os peixes?"], ["I saw it. It was big.", "Eu vi. Era grande."], ["Who had the socks?", "Quem tinha as meias?"], ["June had two pairs.", "A June tinha dois pares."], ["Who ate the melons?", "Quem comeu os melões?"], ["We ate them at noon.", "Nós os comemos ao meio-dia."]], ["O /ɛ/ em went", "Boca meio aberta, como em “pé”: went, not “uente”.", ["went", "We went home."]], ["Ravi ___ to the market.", "went", "goed", "Ravi foi ao mercado.", "Go é irregular: o passado é went, não goed."]];
