content[266]=[[["Noah did not find his key.", "Noah não achou a chave dele."], ["He did not forget it at home.", "Ele não a esqueceu em casa."], ["He looked in his bag and near the PC.", "Ele olhou na bolsa e perto do computador."], ["His girlfriend did not see it on the table.", "A namorada dele não viu a chave na mesa."], ["Then Noah found it in his shoe.", "Então o Noah achou a chave no sapato."]], [["Where is your key?", "Onde está a sua chave?"], ["I did not find it.", "Eu não achei."], ["Is it in your bag?", "Está na sua bolsa?"], ["No, I did not leave it there.", "Não, eu não deixei lá."], ["Do you forget things?", "Você esquece as coisas?"], ["Yes, but I did not forget today.", "Sim, mas hoje eu não esqueci."], ["Where was the key?", "Onde estava a chave?"], ["It was in my shoe. I did not look there.", "Estava no meu sapato. Eu não olhei lá."]], ["Did not ligado", "Diga did not quase junto: “didnót”, com a força em not.", ["not", "I did not see it."]], ["Noah did not ___ his key.", "find", "found", "Noah não achou a chave dele.", "Depois de did not o verbo fica na forma base."]];
