content[267]=[[["Lia visited her aunt on Sunday.", "A Lia visitou a tia no domingo."], ["Ben called Lia that night.", "O Ben ligou para a Lia naquela noite."], ["He wanted to know about the visit.", "Ele queria saber da visita."], ["Lia told him about the horses and the roads.", "A Lia contou a ele sobre os cavalos e as estradas."], ["They talked for an hour.", "Eles conversaram por uma hora."]], [["Did you visit your aunt?", "Você visitou sua tia?"], ["Yes, I did. It was fun.", "Sim. Foi divertido."], ["Did she cook dinner?", "Ela fez o jantar?"], ["Yes, she did. She made soup.", "Fez. Ela fez sopa."], ["Did you call Ben after dinner?", "Você ligou para o Ben depois do jantar?"], ["No, I did not. I was tired.", "Não. Eu estava cansada."], ["Did you see her dog?", "Você viu o cachorro dela?"], ["Yes, I did. It was very big.", "Vi. Era muito grande."]], ["Did you /dɪdʒu/", "Na fala rápida did you soa “dídjiu”: o d e o y se juntam.", ["did", "Did you go?"]], ["___ you visit your aunt?", "Did", "Do", "Você visitou sua tia?", "Pergunta sobre o passado começa com Did."]];
