content[268]=[[["Tina moved to this city two years ago.", "A Tina se mudou para esta cidade há dois anos."], ["She came here with her little dog.", "Ela veio para cá com seu cachorrinho."], ["A week ago she found a new job.", "Há uma semana ela achou um emprego novo."], ["Noah started work three days ago.", "O Noah começou a trabalhar há três dias."], ["Now Tina does not want to move again.", "Agora a Tina não quer se mudar de novo."]], [["When did you come here?", "Quando você veio para cá?"], ["I came here two years ago.", "Eu vim para cá há dois anos."], ["When did you find your job?", "Quando você achou seu emprego?"], ["I found it a week ago.", "Eu achei há uma semana."], ["Did Noah start work too?", "O Noah também começou a trabalhar?"], ["Yes, he started three days ago.", "Sim, ele começou há três dias."], ["Do you want to move again?", "Você quer se mudar de novo?"], ["No, I moved here two years ago.", "Não, eu me mudei para cá há dois anos."]], ["Acento em ago", "A força cai na segunda sílaba: a-GO.", ["ago", "Two days ago."]], ["Tina moved here two years ___.", "ago", "before", "Tina se mudou para cá há dois anos.", "Para dizer “há dois anos” usamos two years ago."]];
