content[270]=[[["Ava and Noah are going to take a trip.", "Ava e Noah vão fazer uma viagem."], ["They are going to visit the coast.", "Eles vão visitar o litoral."], ["Ava is going to pack two small bags.", "A Ava vai arrumar duas malas pequenas."], ["Noah is going to buy a train ticket.", "O Noah vai comprar uma passagem de trem."], ["Noah is going to sleep on the tour bus.", "O Noah vai dormir no ônibus de turismo."]], [["Are you going to take a trip?", "Você vai fazer uma viagem?"], ["Yes, I am going to the coast.", "Sim, vou ao litoral."], ["Are you going to pack tonight?", "Você vai arrumar as malas hoje à noite?"], ["Yes, I am going to pack now.", "Sim, vou arrumar agora."], ["Is Ava going to come?", "A Ava vai?"], ["Yes, she is going to come too.", "Sim, ela também vai."], ["Are you going to take the tour bus?", "Vocês vão pegar o ônibus de turismo?"], ["Yes, we are going to leave at nine.", "Sim, vamos sair às nove."]], ["going to rápido", "Na fala, going to vira “gonna”: GOH-ning tu, com a força em going.", ["going", "I am going to pack."]], ["Ava ___ going to pack two bags.", "is", "are", "A Ava vai arrumar duas malas.", "Com she/Ava usamos is."]];
