content[271]=[[["Tina is leaving her hotel room.", "A Tina está saindo do quarto de hotel."], ["A taxi is waiting outside.", "Um táxi está esperando lá fora."], ["The taxi driver asks where she is going.", "O motorista de táxi pergunta aonde ela vai."], ["She is going to the train station.", "Ela vai para a estação de trem."], ["Lou is going with her and has a city map.", "O Lou vai com ela e leva um mapa da cidade."]], [["Where are you going today?", "Aonde você vai hoje?"], ["I am going to the station.", "Vou para a estação."], ["Who is going with you?", "Quem vai com você?"], ["Lou is going with me.", "O Lou vai comigo."], ["What are you going to do there?", "O que vocês vão fazer lá?"], ["We are going to buy one way tickets.", "Vamos comprar passagens só de ida."], ["Is the taxi going to wait?", "O táxi vai esperar?"], ["Yes, it is going to wait.", "Sim, ele vai esperar."]], ["/w/ em where", "Lábios arredondados para o w, depois “ér”: where, não “uére” com v.", ["where", "Where are you going?"]], ["Where ___ you going?", "are", "is", "Aonde você vai?", "Com you usamos are."]];
