content[274]=[[["Noah looks at a hotel on his phone.", "O Noah olha um hotel no celular."], ["He wants to know about the free wifi.", "Ele quer saber sobre o wifi grátis."], ["The swimming pool is open until nine.", "A piscina fica aberta até as nove."], ["Air conditioning is in every room.", "Tem ar-condicionado em todos os quartos."], ["Noah is happy and says yes.", "O Noah fica feliz e diz sim."]], [["Is breakfast included?", "O café da manhã está incluído?"], ["Yes, it is. It is free.", "Sim, está. É grátis."], ["Is the swimming pool open now?", "A piscina está aberta agora?"], ["Yes, it is open until nine.", "Sim, está aberta até as nove."], ["Is a hair dryer in the room?", "Tem secador de cabelo no quarto?"], ["Yes, it is in the bathroom.", "Sim, está no banheiro."], ["Is the free wifi fast too?", "O wifi grátis também é rápido?"], ["Yes, it is fast everywhere.", "Sim, é rápido em todo lugar."]], ["Acento em breakfast", "A força fica na primeira sílaba: BREK-fust.", ["breakfast", "Breakfast is free."]], ["___ breakfast included?", "Is", "Are", "O café da manhã está incluído?", "Breakfast é singular, então usamos Is."]];
