content[278]=[[["Ben and Tina are at the airport.", "O Ben e a Tina estão no aeroporto."], ["Their flight is at nine.", "O voo deles é às nove."], ["The woman says, “Show your passport, please.”", "A mulher diz: “Mostre seu passaporte, por favor.”"], ["Then they walk to gate twelve.", "Depois eles caminham até o portão doze."], ["They wait near the gift shop.", "Eles esperam perto da loja de presentes."]], [["Excuse me, where is gate twelve?", "Com licença, onde fica o portão doze?"], ["Go straight and turn left. Do not get lost.", "Siga em frente e vire à esquerda. Não se perca."], ["Is my flight on time?", "O meu voo está no horário?"], ["Yes. Please wait here.", "Sim. Por favor, espere aqui."], ["Do I need my passport?", "Preciso do meu passaporte?"], ["Yes, show your passport at the gate.", "Sim, mostre o passaporte no portão."], ["Is the flight at nine?", "O voo é às nove?"], ["Yes, and please do not be late.", "Sim, e por favor não se atrase."]], ["Acento em passport", "A força fica na primeira sílaba: PASS-port.", ["passport", "Show your passport."]], ["___ your passport, please.", "Show", "Showing", "Mostre seu passaporte, por favor.", "O imperativo usa o verbo na forma base."]];
