content[280]=[[["Peg has a party at her house.", "A Peg faz uma festa na casa dela."], ["She puts hot stew on the table.", "Ela põe ensopado quente na mesa."], ["Ravi comes in with fried potatoes.", "O Ravi chega com batatas fritas."], ["Peg asks, “Would you like some tea?”", "A Peg pergunta: “Você quer um pouco de chá?”"], ["Ravi says yes and takes a plate.", "O Ravi diz que sim e pega um prato."]], [["Would you like some stew?", "Você quer um pouco de ensopado?"], ["Yes, please. It looks delicious.", "Sim, por favor. Parece delicioso."], ["Would you like some fried potatoes too?", "Você quer um pouco de batata frita também?"], ["No, thank you. I am not hungry.", "Não, obrigado. Não estou com fome."], ["Would you like some tea then?", "Então quer um pouco de chá?"], ["Yes, I would. Green tea, please.", "Sim, quero. Chá verde, por favor."], ["Would you like some more stew?", "Quer mais um pouco de ensopado?"], ["Yes, one small plate, please.", "Sim, um prato pequeno, por favor."]], ["O som /st/ em stew", "Comece com s e solte o t logo depois: stiu. Não ponha um e antes do s.", ["stew", "Would you like some stew?"]], ["Would you like ___ fried potatoes?", "some", "a", "Você quer um pouco de batata frita?", "Para oferecer comida ou bebida, use Would you like some."]];
