content[281]=[[["Noah stands at the door of the shop.", "O Noah está parado na porta da loja."], ["He says, “Excuse me, can I come in?”", "Ele diz: “Com licença, posso entrar?”"], ["Tina smiles and opens the door for him.", "A Tina sorri e abre a porta para ele."], ["Noah says, “Thank you for your help.”", "O Noah diz: “Obrigado pela sua ajuda.”"], ["Tina says, “You are welcome. Come in!”", "A Tina diz: “De nada. Entre!”"]], [["Excuse me, where is the bank?", "Com licença, onde fica o banco?"], ["It is next to the park.", "Fica ao lado do parque."], ["Thank you for your help.", "Obrigado pela sua ajuda."], ["You are welcome. Is it far?", "De nada. É longe?"], ["Pardon me, is this seat free?", "Perdão, este assento está livre?"], ["Yes, it is, sir. Please sit down.", "Está, sim, senhor. Pode sentar."], ["Thank you for the water.", "Obrigado pela água."], ["You are welcome. Have a nice day.", "De nada. Tenha um bom dia."]], ["O som /θ/ em thank", "Ponha a ponta da língua entre os dentes e sopre. Não troque por t ou f.", ["thank", "Thank you for the water."]], ["Thank you ___ your help.", "for", "to", "Obrigado pela sua ajuda.", "Em inglês, agradecemos por algo com for."]];
