content[282]=[[["Lou sees Ava at the entrance.", "O Lou vê a Ava na entrada."], ["He smiles at her, and she smiles at him.", "Ele sorri para ela, e ela sorri para ele."], ["Ava kisses him on the cheek.", "A Ava dá um beijo na bochecha dele."], ["Ben and June are late, so they call us.", "O Ben e a June estão atrasados, então ligam para nós."], ["We wait for them at the door.", "Nós esperamos por eles na porta."]], [["Do you see Ava over there?", "Você vê a Ava ali?"], ["Yes, I see her. She smiles at me.", "Vejo, sim. Ela sorri para mim."], ["Where are Ben and June?", "Onde estão o Ben e a June?"], ["They are late. I will call them.", "Eles estão atrasados. Eu vou ligar para eles."], ["Do you want to wait for them?", "Você quer esperar por eles?"], ["Yes, please wait with us.", "Sim, espere conosco, por favor."], ["Is Lou here too?", "O Lou está aqui também?"], ["Yes, I see him. Say hello to him.", "Vejo, sim. Diga oi para ele."]], ["O som /h/ em him e her", "O h é só um sopro leve, como um suspiro. Não pronuncie como o r do português.", ["her", "I call her at five."]], ["I see Ava. I wave at ___.", "her", "she", "Eu vejo a Ava. Eu aceno para ela.", "Depois do verbo ou de at, use o pronome objeto her."]];
