content[283]=[[["Nico buys jewelry for his sister.", "O Nico compra joias para a irmã dele."], ["He wraps the box in white paper.", "Ele embrulha a caixa em papel branco."], ["Then he puts a golden ribbon on top.", "Depois ele põe um laço dourado em cima."], ["He cannot go to her house today.", "Ele não pode ir à casa dela hoje."], ["So he sends the gift to her by mail.", "Então ele envia o presente a ela pelo correio."]], [["What do you buy for Mom?", "O que você compra para a mamãe?"], ["I buy a scarf for her.", "Compro um cachecol para ela."], ["Can you wrap it for me?", "Você pode embrulhar para mim?"], ["Sure. I give it to you at six.", "Claro. Eu entrego a você às seis."], ["Do you want a red ribbon too?", "Você quer um laço vermelho também?"], ["Yes, a golden ribbon, please.", "Quero, sim, um laço dourado, por favor."], ["Do you send a card to her?", "Você manda um cartão para ela?"], ["Yes, I send a card to Mom.", "Sim, mando um cartão para a mamãe."]], ["O som /r/ em ribbon e wrap", "Em wrap o w não soa: comece direto com o r inglês, com a língua enrolada para trás sem tocar o céu da boca.", ["wrap", "I wrap a gift for you."]], ["I buy a scarf ___ my mom.", "for", "at", "Eu compro um cachecol para a minha mãe.", "Com buy, a pessoa que recebe vem com for; com give e send, vem com to."]];
