content[287]=[[["Ravi looks for a gift for his uncle.", "O Ravi procura um presente para o tio."], ["Peg says, “What about a scarf?”", "A Peg diz: “Que tal um cachecol?”"], ["The scarf is lovely, cute, and cheap.", "O cachecol é lindo, fofo e barato."], ["Ravi likes the idea but sees a pink hat.", "O Ravi gosta da ideia, mas vê um chapéu rosa."], ["Peg laughs, “Why not buy both?”", "A Peg ri: “Por que não comprar os dois?”"]], [["I need a gift for my uncle.", "Preciso de um presente para o meu tio."], ["What about a scarf?", "Que tal um cachecol?"], ["Good idea. Is this one cheap?", "Boa ideia. Este é barato?"], ["Yes, it is. It is only ten dollars.", "É, sim. Custa só dez dólares."], ["What about a hat for his dog?", "Que tal um chapéu para o cachorro dele?"], ["Why not? His dog is funny.", "Por que não? O cachorro dele é engraçado."], ["Do you like this pink hat?", "Você gosta deste chapéu rosa?"], ["Yes, I do. I will take it.", "Gosto. Vou levar."]], ["O som /s/ em scarf", "Comece com s limpo e depois o c vira /k/: s-karf. Não ponha um e antes (esscarf).", ["scarf", "What about a scarf?"]], ["What ___ a scarf?", "about", "for", "Que tal um cachecol?", "Para sugerir, use What about + coisa."]];
