content[288]=[[["June has a secret for her twin.", "A June tem um segredo para a gêmea dela."], ["She buys grilled fish because her twin loves it.", "Ela compra peixe grelhado porque a gêmea adora."], ["Her twin is alone today, so June visits her.", "A gêmea está sozinha hoje, então a June a visita."], ["She hides the box because it is a surprise.", "Ela esconde a caixa porque é uma surpresa."], ["Her twin opens the box and smiles.", "A gêmea abre a caixa e sorri."]], [["Why do you smile, June?", "Por que você sorri, June?"], ["Because I have a secret.", "Porque eu tenho um segredo."], ["Is it a surprise for your twin?", "É uma surpresa para a sua gêmea?"], ["Yes, it is. She loves grilled fish, so I buy some.", "É, sim. Ela adora peixe grelhado, então eu compro um pouco."], ["Why not tell her now?", "Por que não contar a ela agora?"], ["Because a surprise is more fun.", "Porque uma surpresa é mais divertida."], ["Does your mom know about it?", "A sua mãe sabe disso?"], ["Yes, she helps me because she loves her twin.", "Sabe, sim. Ela me ajuda porque adora a gêmea."]], ["Because sem forçar o be", "Diga /bi-KOZ/, com força na segunda sílaba. Na fala rápida muitos dizem só /kəz/.", ["because", "I smile because I am happy."]], ["I buy grilled fish ___ she loves it.", "because", "so", "Eu compro peixe grelhado porque ela adora.", "Because dá o motivo; so mostra o resultado."]];
