content[289]=[[["Ben plans a party for Peg.", "O Ben planeja uma festa para a Peg."], ["Her birthday is on April twentieth.", "O aniversário dela é no dia vinte de abril."], ["He asks every relative to come at five.", "Ele pede a cada parente que venha às cinco."], ["Ava brings sweets, and Ravi brings a cake.", "A Ava traz doces, e o Ravi traz um bolo."], ["Peg comes in, and everyone says, “Cheers!”", "A Peg entra, e todos dizem: “Saúde!”"]], [["Can you come to the party?", "Você pode vir à festa?"], ["Yes, I can. When is it?", "Posso, sim. Quando é?"], ["It is on April twentieth.", "É no dia vinte de abril."], ["Who is the party for?", "Para quem é a festa?"], ["It is for Peg. Please give her these sweets.", "É para a Peg. Por favor, dê a ela estes doces."], ["Sure. Would you like some cake?", "Claro. Você quer um pouco de bolo?"], ["Yes, thank you. Is it a surprise?", "Quero, obrigado. É uma surpresa?"], ["Yes, so please do not tell her.", "É, então por favor não conte a ela."]], ["O som /p/ em party e Peg", "Feche os lábios e solte um sopro forte. Ponha a mão na frente da boca: você sente o ar.", ["party", "Peg has a party."]], ["Ben calls the relatives ___ they come at five.", "so", "because", "O Ben liga para os parentes, então eles vêm às cinco.", "So mostra o resultado; porque o Ben liga, eles vêm."]];
