content[290]=[[["Ava waits for Lou at the square.", "A Ava espera o Lou na praça."], ["Lou is slim and handsome, about twenty.", "O Lou é magro e bonito, tem uns vinte anos."], ["He has short brown hair and glasses.", "Ele tem cabelo castanho curto e óculos."], ["His grandfather is old, and his hair is grey.", "O avô dele é velho, e o cabelo dele é grisalho."], ["Ava sees him and waves.", "A Ava o vê e acena."]], [["Is Lou the tall boy?", "O Lou é o garoto alto?"], ["Yes, he is. He has glasses.", "É, sim. Ele usa óculos."], ["What color is his hair?", "Qual é a cor do cabelo dele?"], ["He has short brown hair.", "Ele tem cabelo castanho curto."], ["Is he young or old?", "Ele é jovem ou velho?"], ["He is young. He is twenty.", "Ele é jovem. Tem vinte anos."], ["Do you see him near the bench?", "Você o vê perto do banco?"], ["Yes, he is the tall one there.", "Vejo. Ele é o alto ali."]], ["O som /h/ em handsome", "O h é só um sopro leve e o d quase não soa: HAN-sum. Não pronuncie o h como r.", ["handsome", "Lou is handsome."]], ["Lou ___ brown hair.", "has", "is", "O Lou tem cabelo castanho.", "Para cabelo, use has: he has brown hair. Is é para tall, young e old."]];
