content[291]=[[["Noah sits at the table with his coffee.", "O Noah está sentado à mesa com o café."], ["He looks bored and a little lonely.", "Ele parece entediado e um pouco sozinho."], ["Tina comes and says, “You look serious.”", "A Tina chega e diz: “Você parece sério.”"], ["He says his day is long.", "Ele diz que o dia dele é longo."], ["Then she tells a joke, and he smiles.", "Então ela conta uma piada, e ele sorri."]], [["Noah looks bored today.", "O Noah parece entediado hoje."], ["Yes, he works late at night.", "É, ele trabalha até tarde da noite."], ["Does he look lonely too?", "Ele parece sozinho também?"], ["No, he looks happy now.", "Não, ele parece feliz agora."], ["You look serious, Tina.", "Você parece séria, Tina."], ["I am only hungry. I want lunch.", "Estou só com fome. Quero almoçar."], ["Do you want to smile a little?", "Você quer sorrir um pouco?"], ["Yes, I look better with food.", "Quero. Eu fico melhor com comida."]], ["Acento em serious e bored", "Em serious a força vai na primeira sílaba: SE-ri-ous. Em bored, o r é inglês e o d final é leve: BORD.", ["bored", "You look bored."]], ["She ___ happy today.", "looks", "looks like", "Ela parece feliz hoje.", "Antes de adjetivo, use só looks, sem like."]];
