content[293]=[[["Nico shows photos of his city.", "O Nico mostra fotos da cidade dele."], ["This tower is the tallest in town.", "Esta torre é a mais alta da cidade."], ["That palace is the oldest one here.", "Aquele palácio é o mais antigo daqui."], ["The biggest park is near the river.", "O maior parque fica perto do rio."], ["But the best place is my street.", "Mas o melhor lugar é a minha rua."]], [["Which tower is the tallest?", "Qual torre é a mais alta?"], ["This one. It is very high.", "Esta aqui. É muito alta."], ["Is this the biggest palace?", "Este é o maior palácio?"], ["No, the biggest one is in the north.", "Não, a maior fica no norte."], ["What is the best place to eat?", "Qual é o melhor lugar para comer?"], ["The best place is my uncle’s shop.", "O melhor lugar é a loja do meu tio."], ["Is it the cheapest too?", "É a mais barata também?"], ["Yes, and it is the nicest.", "É, e também é a mais agradável."]], ["O som /st/ em biggest e best", "Termine com s e t juntos, sem vogal no meio: bes-t, big-gest. Não diga bestchi.", ["best", "This is the best cake."]], ["This tower is the ___ in town.", "tallest", "most tall", "Esta torre é a mais alta da cidade.", "Adjetivos curtos recebem -est: the tallest."]];
