content[294]=[[["Lou lives on a small street.", "O Lou mora em uma rua pequena."], ["There is a post office on the corner.", "Há uma agência dos correios na esquina."], ["There is a bus stop next to it.", "Há um ponto de ônibus ao lado dele."], ["There are two shops and a burrito place.", "Há duas lojas e uma lanchonete de burrito."], ["There are no cars on Sunday.", "Não há carros no domingo."]], [["What is on your street, Lou?", "O que tem na sua rua, Lou?"], ["There is a post office on the corner.", "Há uma agência dos correios na esquina."], ["Is there a bus stop?", "Tem um ponto de ônibus?"], ["Yes, there is. It is near the post office.", "Tem, sim. Fica perto dos correios."], ["Are there any shops?", "Tem alguma loja?"], ["Yes, there are three shops.", "Tem, sim. Há três lojas."], ["Is there a park too?", "Tem um parque também?"], ["No, but there are trees.", "Não, mas há árvores."]], ["O som /oʊ/ em post", "A boca arredonda e termina num u: poust. O t final é bem suave.", ["post", "The post office is on the corner."]], ["___ two shops on my street.", "There are", "There is", "Há duas lojas na minha rua.", "Com plural (two shops), use There are."]];
