content[295]=[[["Tina likes the oyster bar, but it is noisy.", "A Tina gosta do bar de ostras, mas é barulhento."], ["The park is quiet and very peaceful.", "O parque é quieto e muito tranquilo."], ["She can stay here or walk to the park.", "Ela pode ficar aqui ou caminhar até o parque."], ["She wants quiet, so she goes to the park.", "Ela quer sossego, então vai ao parque."], ["She sits down and reads a book.", "Ela se senta e lê um livro."]], [["Is the oyster bar quiet or noisy?", "O bar de ostras é quieto ou barulhento?"], ["It is noisy, but it is fun.", "É barulhenta, mas é divertida."], ["Is the park peaceful?", "O parque é tranquilo?"], ["Yes, it is clean and quiet.", "É, sim. É limpo e quieto."], ["Do you want to sit here or there?", "Você quer sentar aqui ou lá?"], ["Let us sit in the park.", "Vamos sentar no parque."], ["Why there?", "Por que lá?"], ["I want quiet, so I like the park.", "Eu quero sossego, então gosto do parque."]], ["O som /ɔɪ/ em noisy", "Comece com a boca arredondada e termine num i: NOI-zy. O s no meio soa como z.", ["noisy", "The street is noisy."]], ["It is noisy, ___ it is fun.", "but", "and", "É barulhento, mas é divertido.", "But liga duas ideias que contrastam; and apenas soma."]];
