content[297]=[[["Ava tells Ben about her Sunday.", "A Ava conta ao Ben sobre o domingo dela."], ["First, she begins the day with a long walk.", "Primeiro, ela começa o dia com uma longa caminhada."], ["Then she buys bread at the bakery.", "Depois ela compra pão na padaria."], ["After that, she meets June for coffee.", "Depois disso, ela encontra a June para um café."], ["Finally, she goes home and sleeps.", "Por fim, ela volta para casa e dorme."]], [["What do you do after lunch?", "O que você faz no domingo?"], ["First, I walk by the lake.", "Primeiro, caminho perto do lago."], ["What comes next?", "E depois?"], ["Then I buy some bread.", "Depois compro um pouco de pão."], ["What is your plan after that?", "Qual é o seu plano depois disso?"], ["After that, I call my mother.", "Depois disso, ligo para minha mãe."], ["How does your day finally end?", "Como seu dia termina por fim?"], ["Finally, I read and go to bed.", "Por fim, leio e vou para a cama."]], ["Ritmo em after that", "Diga as duas palavras juntas: AF-ter THAT. O th de that é suave, com a língua entre os dentes.", ["then", "Then I eat lunch."]], ["First I walk. ___ I buy bread.", "Then", "After", "Primeiro eu caminho. Depois eu compro pão.", "Then liga a próxima ação na sequência."]];
