content[298]=[[["Nico has a question for the clerk.", "O Nico tem uma pergunta para o atendente."], ["He asks, “Where is the train to Rome?”", "Ele pergunta: “Onde fica o trem para Roma?”"], ["The clerk gives him an answer and a map.", "O atendente dá a ele uma resposta e um mapa."], ["Nico asks, “When does it leave, and why is it late?”", "O Nico pergunta: “Quando ele sai, e por que está atrasado?”"], ["The clerk says, “Who knows? The rain.”", "O atendente diz: “Quem sabe? A chuva.”"]], [["Who is that woman at the door?", "Quem é aquela mulher na porta?"], ["She is my teacher, Ms. Lou.", "Ela é minha professora, a Lou."], ["What does she teach?", "O que ela ensina?"], ["She teaches English and music.", "Ela ensina inglês e música."], ["Where is her class?", "Onde é a aula dela?"], ["It is in room five.", "É na sala cinco."], ["When does it begin, and why so early?", "Quando começa, e por que tão cedo?"], ["At eight. That is the answer: she likes mornings.", "Às oito. Essa é a resposta: ela gosta de manhã."]], ["Palavras com wh", "Em who o w não soa: /hu/. Em where e when o som é um /w/ suave, com os lábios arredondados.", ["who", "Who is she?"]], ["___ is the train? At six.", "When", "Where", "Quando é o trem? Às seis.", "A resposta é uma hora, então a pergunta é When."]];
