content[299]=[[["Lia sits by the lake with Ravi.", "A Lia está sentada perto do lago com o Ravi."], ["She says, “This is a wonderful place.”", "Ela diz: “Este lugar é maravilhoso.”"], ["They talk about school, food, and music.", "Eles conversam sobre escola, comida e música."], ["Ravi says, “I am ready to go home.”", "O Ravi diz: “Estou pronto para ir para casa.”"], ["They say goodbye and meet again tomorrow.", "Eles se despedem e se encontram de novo amanhã."]], [["Are you ready to go?", "Você está pronto para ir?"], ["Yes, I am. Where do we go?", "Estou. Aonde vamos?"], ["There is a bus stop near the lake.", "Tem um ponto de ônibus perto do lago."], ["Can we ride together?", "Podemos ir juntos?"], ["Sure. What do you do tomorrow?", "Claro. O que você faz amanhã?"], ["I study, and then I cook dinner.", "Eu estudo e depois faço o jantar."], ["Can you come to my house?", "Você pode vir à minha casa?"], ["Yes, I can. Goodbye until tomorrow!", "Posso, sim. Tchau até amanhã!"]], ["Acento em tomorrow e together", "A força vai na segunda sílaba: to-MOR-row, to-GE-ther. Fale com ritmo calmo.", ["together", "We go together."]], ["Are you ___ to go?", "ready", "ready for", "Você está pronto para ir?", "Antes de to + verbo, use ready sem for."]];
patterns[299]=new RegExp("\\b(ready|together|tomorrow|goodbye)\\b","i");
themes[299]="chat";
photos[299]=["photo-lake-1.webp", "photo-friends-1.webp"];
stories[299]=["Lia e a conversa final", "Lia is ready for her last English class.~A Lia está pronta para sua última aula de inglês.|First, she says hello to her teacher.~Primeiro, ela diz oi para a professora.|The teacher asks, “What do you like?”~A professora pergunta: “Do que você gosta?”|Lia answers, “I like music and cake.”~A Lia responde: “Eu gosto de música e bolo.”|There are ten students, and they all clap.~Há dez alunos, e todos batem palmas.|Her friend Ravi is tall, but he is shy.~O amigo dela, o Ravi, é alto, mas é tímido.|Then he asks, “Can we study together?”~Então ele pergunta: “Podemos estudar juntos?”|Lia says yes because she wants a friend.~A Lia diz que sim porque quer um amigo.|After that, they walk to the lake.~Depois disso, eles caminham até o lago.|They say goodbye and meet again tomorrow.~Eles se despedem e se encontram de novo amanhã."];
extras[299]={"goodbye": ["Goodbye, my friend.", "Tchau, meu amigo."], "perfect": ["The day is perfect.", "O dia está perfeito."]};
