content[305]=[[["June shows Tina how to clean a kettle.", "A June mostra à Tina como limpar uma chaleira."], ["First, she fills it at the tap.", "Primeiro, ela a enche na torneira."], ["Then she waits for ten minutes.", "Depois ela espera dez minutos."], ["Tina tries it with her own kettle.", "A Tina tenta com a própria chaleira."], ["Now both kettles look good.", "Agora as duas chaleiras ficam bonitas."]], [["How do you clean a kettle?", "Como você limpa uma chaleira?"], ["First, I fill it at the tap.", "Primeiro, eu a encho na torneira."], ["And then what do you do?", "E depois, o que você faz?"], ["Then I wait and pour it out.", "Depois eu espero e jogo a água fora."], ["How do you wash a big pan?", "Como você lava uma panela grande?"], ["I wash it in the tub.", "Eu a lavo no tanque."], ["How do you wash small cups?", "Como você lava xícaras pequenas?"], ["I put them in the basin.", "Eu as ponho na bacia."]], ["Entonação de How do you…?", "A voz sobe em How e cai no fim da pergunta com palavra de pergunta.", ["kettle", "How do you clean it?"]], ["How ___ you clean a kettle?", "do", "does", "Como você limpa uma chaleira?", "Com you, a pergunta usa do."]];
