content[309]=[[["Lia has to clean the carpet today.", "A Lia tem que limpar o tapete hoje."], ["She works slowly and the walls are white.", "Ela trabalha devagar e as paredes são brancas."], ["She puts polish on the table.", "Ela passa cera na mesa."], ["Ravi asks, Can I help you?", "O Ravi pergunta: Posso ajudar você?"], ["Finally, the carpet is clean.", "Finalmente, o tapete está limpo."]], [["Do you have to clean the carpet?", "Você tem que limpar o tapete?"], ["Yes, I have to clean it today.", "Sim, eu tenho que limpá-lo hoje."], ["Are there marks on the walls?", "Tem marcas nas paredes?"], ["Yes, there is polish on the table too.", "Sim, tem cera na mesa também."], ["Can I help you, Lia?", "Posso ajudar você, Lia?"], ["Yes, please. Carry the box carefully.", "Sim, por favor. Carregue a caixa com cuidado."], ["Are you finishing now?", "Você está terminando agora?"], ["Yes, finally. The whole house is clean.", "Sim, finalmente. A casa inteira está limpa."]], ["O som /ɔː/ em floor", "Arredonde os lábios e alongue o som: floor tem um o longo.", ["floor", "The floor is clean."]], ["Lia ___ clean the carpet today.", "has to", "have to", "A Lia tem que limpar o tapete hoje.", "Com she ou um nome, use has to."]];
