content[310]=[[["Tina is in a clothing store.", "A Tina está numa loja de roupas."], ["She likes those blue caps on the wall.", "Ela gosta daqueles bonés azuis na parede."], ["How much are those caps?", "Quanto custam aqueles bonés?"], ["They are twenty dollars each.", "Custam vinte dólares cada."], ["These bells are cheaper, so she takes them.", "Estes sinos são mais baratos, então ela os leva."]], [["How much are these bells?", "Quanto custam estes sinos?"], ["They are three dollars.", "Custam três dólares."], ["And how much are those caps?", "E quanto custam aqueles bonés?"], ["Those are twenty dollars each.", "Aqueles custam vinte dólares cada."], ["How much are those phones?", "Quanto custam aqueles celulares?"], ["They are ninety dollars each.", "Custam noventa dólares cada."], ["How much are those cups?", "Quanto custam aquelas xícaras?"], ["They are six dollars. Do you like them?", "Custam seis dólares. Você gosta delas?"]], ["O th de these e those", "Ponha a língua entre os dentes e vibre a voz: these, those.", ["these", "These are my caps."]], ["How much ___ these caps?", "are", "is", "Quanto custam estes bonés?", "Caps e these são plural, então use are."]];
