content[313]=[[["Noah walks into a small shop.", "O Noah entra numa loja pequena."], ["I am looking for a shirt with dots, he says.", "Estou procurando uma camisa de bolinhas, diz ele."], ["The clerk shows him a nice one.", "A atendente mostra uma bonita para ele."], ["Can I try it on?", "Posso experimentar?"], ["He looks in the mirror and smiles.", "Ele se olha no espelho e sorri."]], [["Hello. Can I help you?", "Olá. Posso ajudar?"], ["Yes, I am looking for a shirt.", "Sim, estou procurando uma camisa."], ["What are you looking for exactly?", "O que você procura exatamente?"], ["I am looking for one with dots.", "Estou procurando uma de bolinhas."], ["We have two colours. You can try it on.", "Temos duas cores. Você pode experimentar."], ["Where is the mirror?", "Onde fica o espelho?"], ["It is next to the door.", "Fica ao lado da porta."], ["Great. It looks good on me.", "Ótimo. Fica bom em mim."]], ["O som /ŋ/ em looking", "Termine looking com o som nasal ng, sem pronunciar g forte.", ["looking", "I am looking for a hat."]], ["I am ___ for a shirt with dots.", "looking", "look", "Estou procurando uma camisa de bolinhas.", "Para dizer o que está fazendo agora, use am + looking."]];
