content[314]=[[["Lou wants a new T-shirt.", "O Lou quer uma camiseta nova."], ["What size are you?, asks the clerk.", "Que tamanho você usa?, pergunta a atendente."], ["I am medium, but this one is small.", "Eu uso médio, mas esta é pequena."], ["The one with lines comes in large.", "A de listras tem tamanho grande."], ["Lou takes two medium shirts as presents.", "O Lou leva duas camisetas médias de presente."]], [["What size do you need?", "Que tamanho você precisa?"], ["I need a medium, please.", "Preciso de um médio, por favor."], ["What do you want, plain or lines?", "O que você quer, lisa ou listrada?"], ["I want one with lines.", "Quero uma listrada."], ["Is this one large?", "Esta é tamanho grande?"], ["No, it is small. Here is a large.", "Não, é pequena. Aqui está uma grande."], ["Is the large too big for me?", "O grande não é grande demais para mim?"], ["Try the medium. It looks right.", "Experimente o médio. Parece o certo."]], ["Acento em medium", "Force a primeira sílaba: ME-di-um, com o primeiro e longo.", ["medium", "I wear a medium."]], ["What ___ do you need?", "size", "sizes", "Que tamanho você precisa?", "Depois de what, use size no singular para perguntar um tamanho."]];
