content[315]=[[["Nico is at the counter of a bookshop.", "O Nico está no balcão de uma livraria."], ["He wants to pay by card for comics and snack bars.", "Ele quer pagar com cartão por gibis e barras de lanche."], ["Do you accept cards?, he asks.", "Vocês aceitam cartões?, ele pergunta."], ["No, we only take cash today.", "Não, hoje só aceitamos dinheiro."], ["Nico pays in cash and gets his comics.", "O Nico paga em dinheiro e leva seus gibis."]], [["Do you accept cards?", "Vocês aceitam cartões?"], ["No, I am sorry. Only cash.", "Não, sinto muito. Só dinheiro."], ["Do you accept ten-dollar bills?", "Vocês aceitam notas de dez dólares?"], ["Yes, we accept all bills.", "Sim, aceitamos todas as notas."], ["How much are the comics and bars?", "Quanto custam os gibis e as barras?"], ["They are eighteen dollars.", "Custam dezoito dólares."], ["Can I pay by card at the bank?", "Posso pagar com cartão no banco?"], ["No, but there is a bank next door.", "Não, mas tem um banco ao lado."]], ["O som /k/ em cash e card", "Solte o ar de uma vez com a parte de trás da língua: k forte.", ["cash", "I pay in cash."]], ["Do you ___ cards?", "accept", "accepts", "Vocês aceitam cartões?", "Depois de do you, o verbo fica na forma base."]];
