content[316]=[[["A customer is waiting for a table.", "Uma cliente está esperando por uma mesa."], ["The waiter is counting the tables.", "O garçom está contando as mesas."], ["Two boys are looking at the numbers on the wall.", "Dois meninos estão olhando os números na parede."], ["A woman is leaving tips on the table.", "Uma mulher está deixando gorjetas na mesa."], ["Now the waiter is calling the next customer.", "Agora o garçom está chamando o próximo cliente."]], [["What is the customer doing?", "O que a cliente está fazendo?"], ["She is waiting for a table.", "Ela está esperando por uma mesa."], ["What is the waiter doing?", "O que o garçom está fazendo?"], ["He is counting the tables.", "Ele está contando as mesas."], ["Are the boys reading the menu?", "Os meninos estão lendo o cardápio?"], ["No, they are only looking at the numbers.", "Não, eles só estão olhando os números."], ["Does the waiter count every table?", "O garçom conta todas as mesas?"], ["Yes, he counts them one by one.", "Sim, ele as conta uma por uma."]], ["O -ing em counting", "Termine com o som nasal ng e sem g forte: coun-ting.", ["counting", "I am counting tables."]], ["The waiter ___ the tables.", "is counting", "counts", "O garçom está contando as mesas.", "Para uma ação agora, use is + verbo-ing."]];
