content[318]=[[["Ravi is in a shop at the train station.", "O Ravi está numa loja da estação de trem."], ["He likes the new snack sticks and drinks.", "Ele gosta das novas palitos de lanche e das bebidas."], ["He asks the clerk to show them to him.", "Ele pede ao atendente que as mostre a ele."], ["The clerk gives them to Ravi.", "O atendente as dá ao Ravi."], ["They taste great, so he buys them.", "Elas são ótimas, então ele as compra."]], [["Can you show me those snack sticks?", "Você pode me mostrar aquelas palitos de lanche?"], ["Sure. Here are the sticks.", "Claro. Aqui estão os palitos."], ["Can I try one of the drinks?", "Posso provar uma das bebidas?"], ["Yes, take it. Do you like them?", "Sim, pegue. Você gosta delas?"], ["Yes, I like them. How much are they?", "Sim, gosto delas. Quanto custam?"], ["The price is two dollars each.", "O preço é dois dólares cada."], ["Can you give me a bag for them?", "Pode me dar uma sacola para elas?"], ["Of course. I will put them in for you.", "Claro. Eu as coloco para você."]], ["O som /θ/ em them... e /ð/", "Em them, ponha a língua entre os dentes e vibre a voz: /ðem/.", ["them", "I like them."]], ["I like the snack sticks. I want to buy ___.", "them", "it", "Eu gosto dos palitos de lanche. Quero comprá-los.", "Sticks é plural, então o pronome é them."]];
