content[319]=[[["Lia is in a shop with Ben.", "A Lia está numa loja com o Ben."], ["She is looking for a new radio.", "Ela está procurando um rádio novo."], ["The gray radio is too expensive.", "O rádio cinza é caro demais."], ["The white one is cheaper than the gray one.", "O branco é mais barato do que o cinza."], ["She buys it and says thanks.", "Ela o compra e agradece."]], [["What are you looking for?", "O que você está procurando?"], ["I am looking for a radio.", "Estou procurando um rádio."], ["How much is this radio?", "Quanto custa este rádio?"], ["It is eighty dollars.", "Custa oitenta dólares."], ["Is it cheaper than that one?", "É mais barato do que aquele?"], ["Yes, that one is sixty dollars.", "Sim, aquele custa sessenta dólares."], ["Is the price higher in this shop?", "O preço é mais alto nesta loja?"], ["No, it is the same. I will buy it today.", "Não, é o mesmo. Vou comprá-lo hoje."]], ["O som /aɪ/ em buy", "Diga “bái”: buy rima com my e tem o u mudo.", ["buy", "I buy a radio."]], ["The white radio is ___ than the gray one.", "cheaper", "more cheap", "O rádio branco é mais barato do que o cinza.", "Adjetivos curtos fazem o comparativo com -er."]];
