content[320]=[[["Peg wants to open an account.", "A Peg quer abrir uma conta."], ["There is a small bank near her house.", "Tem um banco pequeno perto da casa dela."], ["There is a clerk at the first desk.", "Tem uma atendente na primeira mesa."], ["Peg shows her passport and asks for a credit card.", "A Peg mostra o passaporte e pede um cartão de crédito."], ["She puts fifty dollars in the new account.", "Ela põe cinquenta dólares na conta nova."]], [["I want to open an account.", "Quero abrir uma conta."], ["Sure. Is there a form to fill?", "Claro. Tem um formulário para preencher?"], ["Yes, there is one on the desk.", "Sim, tem um na mesa."], ["Do you want a credit card, too?", "Você quer um cartão de crédito também?"], ["Yes. Is there a limit of one thousand dollars?", "Sim. Tem limite de mil dólares?"], ["No, there is a limit of fifty dollars at first.", "Não, no começo o limite é de cinquenta dólares."], ["Do you want to make a deposit today?", "Você quer fazer um depósito hoje?"], ["Yes, fifty dollars. I do not have a million!", "Sim, cinquenta dólares. Eu não tenho um milhão!"]], ["Acento em credit", "Force a primeira sílaba: CRED-it. O i do fim é curto.", ["credit", "I have a credit card."]], ["There ___ a bank near my house.", "is", "are", "Tem um banco perto da minha casa.", "Bank é singular, então use there is."]];
