content[321]=[[["June wants to send two letters to Brazil.", "A June quer mandar duas cartas para o Brasil."], ["She goes to the mail office.", "Ela vai ao correio."], ["How much are the stamps for them?", "Quanto custam os selos para elas?"], ["How long does it take to get there?", "Quanto tempo leva para chegar lá?"], ["It takes eleven days, the clerk says.", "Leva onze dias, diz a atendente."]], [["I want to send these letters to Brazil.", "Quero enviar estas cartas para o Brasil."], ["Okay. Write the address here.", "Certo. Escreva o endereço aqui."], ["And how much are the stamps to Brazil?", "E quanto custam os selos para o Brasil?"], ["Two stamps to Brazil are thirteen dollars.", "Dois selos para o Brasil custam treze dólares."], ["How long will it take to arrive?", "Quanto tempo vai levar para chegar?"], ["It takes about eleven days.", "Leva cerca de onze dias."], ["Can I send them today?", "Posso enviá-las hoje?"], ["Yes, the mail leaves at four.", "Sim, o correio sai às quatro."]], ["O som /æ/ em address", "Abra bem a boca no primeiro a: a-DRESS, com acento na segunda sílaba.", ["address", "Write your address."]], ["How ___ does it take?", "long", "much", "Quanto tempo leva?", "Para perguntar o tempo, use how long; how much é para preço."]];
