content[322]=[[["Noah goes to the library after school.", "O Noah vai à biblioteca depois da escola."], ["It is quiet, and many people are reading.", "Está tranquilo, e muita gente está lendo."], ["Can I borrow these novels?", "Posso pegar estes romances emprestados?"], ["Yes, but they are due on Mondays.", "Sim, mas vencem às segundas-feiras."], ["He wants to read them at home.", "Ele quer lê-los em casa."]], [["Can I borrow this novel?", "Posso pegar este romance emprestado?"], ["Yes. Please show me your card.", "Sim. Mostre-me seu cartão, por favor."], ["Here it is. When is it due?", "Aqui está. Quando vence?"], ["It is due on Mondays.", "Vence às segundas-feiras."], ["Can I return it at the desk?", "Posso devolvê-lo no balcão?"], ["Yes, put it in the children section.", "Sim, ponha na seção infantil."], ["Can I borrow two articles?", "Posso pegar dois artigos emprestados?"], ["Yes, you can copy three articles.", "Sim, você pode copiar três artigos."]], ["O som /ʌ/ em due... e library", "Em library, acentue a primeira sílaba: LI-bra-ry.", ["library", "I go to the library."]], ["Can I ___ this book?", "borrow", "lend", "Posso pegar este livro emprestado?", "Quem pede emprestado usa borrow; lend é quem empresta."]];
