content[323]=[[["The bank closes at five in the evening.", "O banco fecha às cinco da tarde."], ["The post office opens at nine in the morning.", "O correio abre às nove da manhã."], ["On Saturdays, Tina goes to the bank.", "Aos sábados, a Tina vai ao banco."], ["In August, she wants to travel.", "Em agosto, ela quer viajar."], ["She finishes her letter at midnight.", "Ela termina a carta à meia-noite."]], [["What time does the bank close?", "A que horas o banco fecha?"], ["It closes at five in the evening.", "Fecha às cinco da tarde."], ["What day do you go there?", "Em que dia você vai lá?"], ["I go on Saturdays.", "Eu vou aos sábados."], ["When do you want to travel?", "Quando você quer viajar?"], ["I want to travel in August.", "Quero viajar em agosto."], ["What day is the trip?", "Que dia é a viagem?"], ["It is on August twenty.", "É no dia vinte de agosto."]], ["O som /ɪ/ em in", "Mantenha o i curto, como em “início”, sem esticar: in, it, is.", ["evening", "I sleep in the evening."]], ["I go to the bank ___ Saturdays.", "on", "at", "Eu vou ao banco aos sábados.", "Para dias da semana, use on."]];
