content[324]=[[["The library is open from nine to six.", "A biblioteca fica aberta das nove às seis."], ["It is closed on Mondays.", "Ela fica fechada às segundas-feiras."], ["Ava goes there on Saturday morning.", "A Ava vai lá no sábado de manhã."], ["The sign says: open on weekdays.", "A placa diz: aberta em dias úteis."], ["She comes back on Tuesday.", "Ela volta na terça-feira."]], [["What time is the library open?", "A que horas a biblioteca fica aberta?"], ["It is open from nine to six.", "Ela fica aberta das nove às seis."], ["Is it open on Mondays?", "Ela abre às segundas-feiras?"], ["No, it is closed on Mondays.", "Não, ela fica fechada às segundas-feiras."], ["Is it open until eight on Friday?", "Ela fica aberta até as oito na sexta?"], ["Yes, it is open until eight.", "Sim, ela fica aberta até as oito."], ["Is it open on weekdays?", "Ela abre nos dias úteis?"], ["Yes, it is open every weekday.", "Sim, ela abre em todo dia útil."]], ["O som /z/ em closed", "Em closed, o s soa como z e o ed soa como d: /kloʊzd/.", ["closed", "The shop is closed."]], ["The library is open ___ nine to six.", "from", "on", "A biblioteca fica aberta das nove às seis.", "Para um período de horas, use from … to …."]];
