content[326]=[[["Tina is new in the city.", "A Tina é nova na cidade."], ["She needs a restroom before the bus.", "Ela precisa de um banheiro antes do ônibus."], ["A man says, \"Go straight, then turn right at the lights.\"", "Um homem diz: \"Siga em frente, depois vire à direita no semáforo.\""], ["The restroom is up the steps behind the post office.", "O banheiro fica subindo os degraus atrás do correio."], ["Then Tina finds her bus stop.", "Aí a Tina encontra o ponto de ônibus."]], [["Excuse me, where is the restroom?", "Com licença, onde fica o banheiro?"], ["It is up the steps, behind the post office.", "Fica subindo os degraus, atrás do correio."], ["Is there a bus stop near here?", "Tem um ponto de ônibus perto daqui?"], ["Yes, go straight for two blocks.", "Sim, siga em frente por dois quarteirões."], ["Excuse me, where is Main Street?", "Com licença, onde fica a Main Street?"], ["Turn right at the lights.", "Vire à direita no semáforo."], ["Is there a bank on that street?", "Tem um banco naquela rua?"], ["Yes, it is next to the bakery.", "Sim, fica ao lado da padaria."]], ["Entonação em Excuse me", "Comece com o tom médio e suba um pouco no fim de Excuse me para soar educado.", ["excuse", "Excuse me, please."]], ["Excuse me, ___ the restroom?", "where is", "where are", "Com licença, onde fica o banheiro?", "Restroom está no singular, então usamos where is."]];
