content[328]=[[["Peg buys a clock at a small shop.", "A Peg compra um relógio numa loja pequena."], ["It costs fifteen dollars.", "Custa quinze dólares."], ["She gives eighteen dollars and waits for her change.", "Ela dá dezoito dólares e espera o troco."], ["The man gives her three dollars back.", "O homem devolve três dólares a ela."], ["The sale ends on June third.", "A liquidação termina em três de junho."]], [["How much is this clock?", "Quanto custa este relógio?"], ["The small one is fifteen dollars.", "O pequeno custa quinze dólares."], ["I have eighteen dollars.", "Tenho dezoito dólares."], ["Then here is your change, three dollars.", "Então aqui está o seu troco, três dólares."], ["And how much is that big clock?", "E quanto custa aquele relógio grande?"], ["That one is ninety dollars.", "Aquele custa noventa dólares."], ["When is the sale over?", "Quando acaba a liquidação?"], ["It ends on June third.", "Termina em três de junho."]], ["Treze ou trinta", "Em thirteen o acento está no fim, em thirty está no começo.", ["thirteen", "Thirteen dollars, please."]], ["The big clock is ___ dollars.", "ninety", "nineteen", "O relógio grande custa noventa dólares.", "Ninety termina em -ty, com acento no começo; nineteen termina em -teen."]];
