content[329]=[[["Lou has four jobs to do this morning.", "O Lou tem quatro tarefas para fazer esta manhã."], ["First, he needs a stamp for an envelope.", "Primeiro, ele precisa de um selo para um envelope."], ["Excuse me, where is the post office?", "Com licença, onde fica o correio?"], ["It is at seventeen Main Street.", "Fica na Main Street, 17."], ["Lou waits in line for fourteen minutes.", "O Lou espera na fila por quatorze minutos."]], [["What time does the post office open?", "A que horas o correio abre?"], ["It opens at nine every day.", "Abre às nove todos os dias."], ["Is there a line at the desk?", "Tem fila no balcão?"], ["Yes, and you are number sixteen.", "Sim, e você é o número dezesseis."], ["How much is one stamp?", "Quanto custa um selo?"], ["It is seventy cents.", "Custa setenta centavos."], ["When does the mail go out?", "Quando sai a correspondência?"], ["It goes out at four o’clock.", "Sai às quatro horas."]], ["Som de st em stamp", "Diga s e t juntos, sem vogal antes: stamp, não estamp.", ["stamp", "One stamp, please."]], ["The mail ___ at four o’clock.", "goes out", "go out", "A correspondência sai às quatro horas.", "Mail é singular, então o verbo leva -es."]];
