content[330]=[[["Lia makes a big dinner for friends.", "Lia faz um grande jantar para os amigos."], ["She asks Ben, \"Would you like to eat with us?\"", "Ela pergunta ao Ben: \"Você gostaria de comer com a gente?\""], ["Ben says, \"Yes, I would.\"", "Ben diz: \"Sim, eu gostaria.\""], ["Lia asks Ava, \"Would you like to bring wine?\"", "Lia pergunta à Ava: \"Você gostaria de trazer vinho?\""], ["Ava says, \"No, thank you. I am busy.\"", "Ava diz: \"Não, obrigada. Estou ocupada.\""]], [["Would you like to have dinner with us?", "Você gostaria de jantar com a gente?"], ["Yes, I would. What do you cook?", "Sim, gostaria. O que você cozinha?"], ["We cook meat with rice and beans.", "Nós fazemos carne com arroz e feijão."], ["Would you like to bring wine?", "Você gostaria de trazer vinho?"], ["Yes, I would. I have a bottle.", "Sim, gostaria. Eu tenho uma garrafa."], ["Great. We eat at seven, then.", "Ótimo. Então comemos às sete."], ["Would you like to bring a buddy?", "Você gostaria de levar um amigão?"], ["No, thank you. My buddy is busy.", "Não, obrigado. Meu amigão está ocupado."]], ["Would you", "Junte would e you num som só: woodjoo.", ["would", "Would you like tea?"]], ["___ you like to join us?", "Would", "Do", "Você gostaria de se juntar a nós?", "Para convite cortês usamos Would you like to."]];
