content[331]=[[["Noah and Tina have plans for Saturday.", "Noah e Tina têm planos para o sábado."], ["Noah is going to run in the park with friends.", "Noah vai correr no parque com os amigos."], ["Tina is going to surf at the beach.", "Tina vai surfar na praia."], ["Their friends are going to gather at the playground.", "Os amigos deles vão se reunir no parquinho."], ["They are not going to stay home.", "Eles não vão ficar em casa."]], [["What are you going to do on Saturday?", "O que você vai fazer no sábado?"], ["I am going to run in the park.", "Eu vou correr no parque."], ["Where are you going to start?", "Onde você vai começar?"], ["We are going to gather at the playground.", "Nós vamos nos reunir no parquinho."], ["Is Tina going to surf?", "A Tina vai surfar?"], ["Yes, she is going to surf at ten.", "Sim, ela vai surfar às dez."], ["Is it going to rain?", "Vai chover?"], ["No, it is going to be sunny.", "Não, vai fazer sol."]], ["Going to rápido", "Na fala natural, going to vira algo como gonna, mas escreva por extenso.", ["going", "I am going to swim."]], ["We ___ going to camp by the lake.", "are", "is", "Nós vamos acampar perto do lago.", "Com we, o verbo be correto é are."]];
