content[332]=[[["Peg and Lou are at the theatre.", "Peg e Lou estão no teatro."], ["The opera starts at seven.", "A ópera começa às sete."], ["There are two seats in row F.", "Há dois lugares na fileira F."], ["There is a long line at the door.", "Há uma fila longa na porta."], ["Lou buys two cold drinks for the performance.", "Lou compra duas bebidas geladas para a apresentação."]], [["Two tickets for the seven o’clock opera, please.", "Dois ingressos para a ópera das sete, por favor."], ["There are two seats in row F.", "Há dois lugares na fileira F."], ["What time does the opera start?", "A que horas a ópera começa?"], ["It starts at seven ten.", "Começa às sete e dez."], ["Is there an actress in this opera?", "Tem uma atriz nessa ópera?"], ["Yes, there is one, and she is great.", "Sim, tem uma, e ela é ótima."], ["Is there a seat near the door?", "Tem um lugar perto da porta?"], ["Yes, there are two in row A.", "Sim, tem dois na fileira A."]], ["Opera", "Diga O-pra, com acento na primeira sílaba e o a final fraco.", ["opera", "The opera is long."]], ["___ two seats in row F.", "There are", "There is", "Há dois assentos na fileira F.", "Two seats é plural, então usamos There are."]];
