content[333]=[[["June loves swimming after class.", "June adora nadar depois da aula."], ["Her friend Nico likes watching cricket on Sundays.", "O amigo dela, Nico, gosta de assistir críquete aos domingos."], ["He hates running, but he loves dancing.", "Ele odeia correr, mas adora dançar."], ["June hates cooking, but she loves singing.", "June odeia cozinhar, mas adora cantar."], ["They both love watching golfers on TV.", "Os dois adoram assistir golfistas na TV."]], [["Do you have a hobby?", "Você tem um hobby?"], ["Yes, I love swimming.", "Sim, eu adoro nadar."], ["Do you also like playing cricket?", "Você também gosta de jogar críquete?"], ["No, I hate playing cricket.", "Não, eu odeio jogar críquete."], ["What do you like doing on Sundays?", "O que você gosta de fazer aos domingos?"], ["I like cooking with my mother.", "Eu gosto de cozinhar com minha mãe."], ["Does Nico like running?", "O Nico gosta de correr?"], ["Yes, he loves running in the park.", "Sim, ele adora correr no parque."]], ["O som -ing", "Termine com o som nasal do n de banco, sem pronunciar o g forte.", ["playing", "I love playing."]], ["I love ___ in the park.", "running", "run", "Eu adoro correr no parque.", "Depois de love usamos o verbo com -ing."]];
