content[337]=[[["Last Saturday Tina went to a town celebration.", "No sábado passado a Tina foi a uma celebração da cidade."], ["People danced in a big circle in the square.", "As pessoas dançaram em um grande círculo na praça."], ["Tina ate corn and drank cold juice.", "Tina comeu milho e bebeu suco gelado."], ["Then she went to a disco with Lou.", "Depois ela foi a uma discoteca com o Lou."], ["It was a crazy and great night.", "Foi uma noite maluca e ótima."]], [["Where did you go on Saturday?", "Aonde você foi no sábado?"], ["I went to the town celebration.", "Eu fui à celebração da cidade."], ["Did you see the dancers?", "Você viu os dançarinos?"], ["Yes, I saw them with Lou.", "Sim, eu os vi com o Lou."], ["What did you eat there?", "O que você comeu lá?"], ["I ate corn and a big cookie.", "Eu comi milho e um biscoito grande."], ["Did you go to the disco?", "Você foi à discoteca?"], ["Yes, I stayed until ten.", "Sim, eu fiquei até as dez."]], ["-ed no passado", "Depois de som surdo, -ed soa como t: danced. Depois de som sonoro, soa d.", ["danced", "Tina danced in a circle."]], ["Tina ___ to a celebration last Saturday.", "went", "go", "Tina foi a uma celebração no sábado passado.", "Com last Saturday usamos o passado: went, não go."]];
