content[338]=[[["There is a snowstorm, so Peg goes to a café.", "Tem uma nevasca, então Peg vai a um café."], ["She wants hot soup because she is cold.", "Ela quer sopa quente porque está com frio."], ["She loves the warmth, so she sits inside.", "Ela adora o calor aconchegante, então senta lá dentro."], ["She skips the cake because it is too sweet.", "Ela dispensa o bolo porque é doce demais."], ["Peg stays because the soup is good.", "Peg fica porque a sopa é boa."]], [["Why are you at the café?", "Por que você está no café?"], ["Because there is a snowstorm.", "Porque tem uma nevasca."], ["Why do you want soup?", "Por que você quer sopa?"], ["Because I am cold and hungry.", "Porque estou com frio e fome."], ["Do you want a hot drink?", "Você quer uma bebida quente?"], ["No, the heat is on, so tea is fine.", "Não, o aquecimento está ligado, então chá basta."], ["Why do you stay here?", "Por que você fica aqui?"], ["Because my mate is late, so I wait.", "Porque meu amigo está atrasado, então eu espero."]], ["Because", "Diga bi-KOZ; o s final soa como z.", ["because", "I stay because it is warm."]], ["There is a snowstorm, ___ Peg goes to a café.", "so", "because", "Tem uma nevasca, então Peg vai a um café.", "So mostra o resultado; because mostra a razão."]];
