content[339]=[[["Ben has a busy weekend of events.", "Ben tem um fim de semana cheio de eventos."], ["Ava asks, \"Would you like to see an exhibition?\"", "Ava pergunta: \"Você gostaria de ver uma exposição?\""], ["Ben says, \"Yes, I would,\" and takes his camera.", "Ben diz: \"Sim, eu gostaria\" e leva a câmera."], ["The exhibition is about nature.", "A exposição é sobre a natureza."], ["On Sunday he is going to rest, because he is tired.", "No domingo ele vai descansar, porque está cansado."]], [["Would you like to see the exhibition?", "Você gostaria de ver a exposição?"], ["Yes, I would. When does it start?", "Sim, gostaria. Quando começa?"], ["It starts at five on Saturday.", "Começa às cinco no sábado."], ["Can I take photos there?", "Posso tirar fotos lá?"], ["Yes, you can take photos there.", "Sim, você pode tirar fotos lá."], ["What luck! The event is free.", "Que sorte! O evento é grátis."], ["Are you going to rest on Sunday?", "Você vai descansar no domingo?"], ["Yes, I am, because I am tired.", "Sim, vou, porque estou cansado."]], ["Event e exhibition", "Em event, o acento está na segunda sílaba: i-VENT.", ["event", "The event is free."]], ["I am tired, ___ I am going to rest.", "so", "because", "Estou cansado, então vou descansar.", "So liga o motivo ao resultado: estou cansado, então descanso."]];
