content[340]=[[["Lou runs a small quiz at school.", "Lou faz um quiz pequeno na escola."], ["He asks, \"Which continent is Brazil on?\"", "Ele pergunta: \"Em qual continente fica o Brasil?\""], ["Ava knows the country and the capital.", "Ava conhece o país e a capital."], ["Noah asks why people speak Portuguese there.", "Noah pergunta por que lá se fala português."], ["Lou smiles, because the class loves quizzes.", "Lou sorri, porque a turma adora quizzes."]], [["Who knows this country?", "Quem conhece este país?"], ["I do. It is Brazil.", "Eu conheço. É o Brasil."], ["Where is the capital?", "Onde fica a capital?"], ["It is in the middle of the country.", "Fica no meio do país."], ["What language do they speak?", "Que idioma eles falam?"], ["They speak Portuguese.", "Eles falam português."], ["How big is the country?", "Quão grande é o país?"], ["It is very big and green.", "É muito grande e verde."]], ["Why e where", "Em why use o w arredondado; em where, o h não soa.", ["where", "Where is the capital?"]], ["___ is the capital?", "Where", "Who", "Onde fica a capital?", "Para lugar usamos where."]];
