content[341]=[[["Ben has his first day at a new school.", "Ben tem o primeiro dia em uma escola nova."], ["He is eager, but he is also awkward.", "Ele está animado, mas também está sem jeito."], ["His sister says, \"You are not alone.\"", "A irmã dele diz: \"Você não está sozinho.\""], ["Ben is not mad. He is only a little tired.", "Ben não está bravo. Ele só está um pouco cansado."], ["Now they are both at the school gate.", "Agora os dois estão no portão da escola."]], [["Are you eager today?", "Você está animado hoje?"], ["Yes, I am. I am a little awkward.", "Sim, estou. Estou um pouco sem jeito."], ["Is your sister mad?", "Sua irmã está brava?"], ["No, she is not mad. She is happy.", "Não, ela não está brava. Está feliz."], ["Are we late for class?", "Estamos atrasados para a aula?"], ["No, we are not late.", "Não, não estamos atrasados."], ["Is the teacher weird today?", "A professora está estranha hoje?"], ["No, she is not weird. She is funny.", "Não, ela não está estranha. Ela é engraçada."]], ["Am, is, are", "Am e are são fracos na frase; is é curto. Fale rápido: I am, she is.", ["eager", "I am eager."]], ["She ___ not mad.", "is", "are", "Ela não está brava.", "Com she usamos is, não are."]];
