content[342]=[[["Tina works in a bookshop.", "Tina trabalha em uma livraria."], ["She loves poetry, and she reads it daily.", "Ela adora poesia e lê todo dia."], ["Her favorite poet is a woman from Spain.", "A poeta favorita dela é uma mulher da Espanha."], ["Tina does not work on Sundays.", "Tina não trabalha aos domingos."], ["After work she goes home with a friend.", "Depois do trabalho ela vai para casa com uma amiga."]], [["Do you sell novels here?", "Vocês vendem romances aqui?"], ["Yes, we do. We sell them every day.", "Sim, vendemos. Vendemos todo dia."], ["Does your shop sell poetry?", "Sua loja vende poesia?"], ["Yes, it does. The books are ten dollars.", "Sim, vende. Os livros custam dez dólares."], ["What do customers usually buy?", "O que os clientes costumam comprar?"], ["They buy novels and poems.", "Eles compram romances e poemas."], ["Does Tina open the shop?", "A Tina abre a loja?"], ["Yes, she opens it at nine.", "Sim, ela abre às nove."]], ["Terceira pessoa com -s", "Em loves o -s soa como z; em works soa como s.", ["loves", "She loves poetry."]], ["Tina ___ not work on Sundays.", "does", "do", "A Tina não trabalha aos domingos.", "Com Tina usamos does not + verbo base."]];
