content[343]=[[["Noah looks out of his window.", "Noah olha pela janela."], ["A guy is holding a red umbrella.", "Um cara está segurando um guarda-chuva vermelho."], ["A man is wearing a long coat.", "Um homem está vestindo um casaco longo."], ["Two boys are running to the bus.", "Dois meninos estão correndo para o ônibus."], ["Noah is listening to the rain and smiling.", "Noah está ouvindo a chuva e sorrindo."]], [["What are you doing at the window?", "O que você está fazendo na janela?"], ["I am looking at the street.", "Estou olhando a rua."], ["Who is holding the umbrella?", "Quem está segurando o guarda-chuva?"], ["The guy in the blue boots.", "O cara de botas azuis."], ["Is he wearing a hat?", "Ele está usando um chapéu?"], ["No, he is wearing a scarf.", "Não, ele está usando um cachecol."], ["Is the other man a stranger?", "O outro homem é um desconhecido?"], ["Yes, I do not know him.", "Sim, eu não o conheço."]], ["Verbos com -ing", "Em holding e wearing, o -ing soa como ing nasal, sem g forte.", ["holding", "She is holding a bag."]], ["A man ___ a long coat.", "is wearing", "wears", "Um homem está usando um casaco longo.", "Para ação agora usamos is + verbo com -ing."]];
