content[345]=[[["Ravi has to build a new bookshelf.", "Ravi tem que construir uma estante nova."], ["He wants to finish before dinner.", "Ele quer terminar antes do jantar."], ["Ava can help, but she has to clean first.", "Ava pode ajudar, mas tem que limpar antes."], ["She cannot find the right tool.", "Ela não acha a ferramenta certa."], ["Ravi wants to eat, so they stop.", "Ravi quer comer, então eles param."]], [["Can you build this bookshelf?", "Você consegue montar esta estante?"], ["Yes, I can. I have a tool.", "Sim, consigo. Eu tenho uma ferramenta."], ["Do you have to mend the slipper too?", "Você também tem que consertar o chinelo?"], ["Yes, I have to finish this job.", "Sim, tenho que terminar este trabalho."], ["What do you want to do later?", "O que você quer fazer mais tarde?"], ["I want to watch a movie.", "Eu quero assistir a um filme."], ["Can Ava help us?", "A Ava pode nos ajudar?"], ["She can, but she has to clean.", "Pode, mas ela tem que limpar."]], ["Have to e has to", "Em has to o s soa como z e to fica fraco: haz-tu.", ["build", "I can build it."]], ["Ava ___ to clean first.", "has", "have", "A Ava tem que limpar primeiro.", "Com Ava usamos has to."]];
