content[346]=[[["Nico rode his bike to the lake yesterday.", "Nico foi de bicicleta ao lago ontem."], ["The road was long, but the day was sunny.", "A estrada era longa, mas o dia estava ensolarado."], ["He had trouble near the bridge.", "Ele teve problemas perto da ponte."], ["A woman showed him the path.", "Uma mulher mostrou o caminho a ele."], ["Then he wandered by the lake and had lunch.", "Depois ele passeou pelo lago e almoçou."]], [["Where did you ride yesterday?", "Onde você andou de bicicleta ontem?"], ["I rode to the lake.", "Eu fui de bicicleta ao lago."], ["Did you have trouble on the road?", "Você teve problemas na estrada?"], ["Yes, I was lost for ten minutes.", "Sim, fiquei perdido por dez minutos."], ["Did anyone help you?", "Alguém ajudou você?"], ["Yes, a woman showed me the path.", "Sim, uma mulher me mostrou o caminho."], ["Was your bike okay?", "Sua bicicleta ficou bem?"], ["Yes, it only fell in a bush.", "Sim, ela só caiu em um arbusto."]], ["Rode e road", "Rode e road soam igual: o longo, com ôu final.", ["rode", "I rode home."]], ["Nico ___ lost near the bridge.", "was", "were", "Nico estava perdido perto da ponte.", "Com Nico, no passado, usamos was."]];
