content[347]=[[["June is going to fly to Toronto.", "June vai voar para Toronto."], ["She is going to meet her cousin there.", "Ela vai encontrar a prima lá."], ["Her airplane is going to leave at nine.", "O avião dela vai partir às nove."], ["At the airport she is going to find gate nine.", "No aeroporto ela vai achar o portão nove."], ["Her cousin is going to wait at the door.", "A prima dela vai esperar na porta."]], [["When are you going to fly?", "Quando você vai voar?"], ["I am going to fly on Monday.", "Eu vou voar na segunda."], ["Are you going abroad?", "Você vai para o exterior?"], ["Yes, I am going to Toronto.", "Sim, vou para Toronto."], ["Is it going to be a small airplane?", "Vai ser um avião pequeno?"], ["No, it is going to be a big jet.", "Não, vai ser um jato grande."], ["Is your cousin going to meet you?", "Sua prima vai encontrar você?"], ["Yes, she is going to be at the gate.", "Sim, ela vai estar no portão."]], ["Airplane e gate", "Em airplane o acento fica em AIR; em gate o a soa como ei.", ["gate", "The gate is open."]], ["I ___ going to fly on Monday.", "am", "is", "Vou voar na segunda.", "Com I usamos am going to."]];
