content[349]=[[["Lia goes to a party and meets Ben.", "Lia vai a uma festa e conhece o Ben."], ["She says hello and asks about his day.", "Ela diz oi e pergunta sobre o dia dele."], ["Ben wakes up early. He is a businessman.", "Ben acorda cedo. Ele é empresário."], ["His ambition is to travel to Japan.", "A ambição dele é viajar para o Japão."], ["Next year he is going to start a trip.", "No ano que vem ele vai começar uma viagem."]], [["Let me introduce myself. I am Lia.", "Deixe-me me apresentar. Eu sou a Lia."], ["Nice to meet you, Lia. I am Ben.", "Prazer, Lia. Eu sou o Ben."], ["What do you do every day?", "O que você faz todo dia?"], ["I wake up at six and work.", "Eu acordo às seis e trabalho."], ["What is your ambition?", "Qual é a sua ambição?"], ["My ambition is to travel to Japan.", "Minha ambição é viajar para o Japão."], ["Are you going to go this year?", "Você vai este ano?"], ["Yes, I am going to leave in June.", "Sim, vou partir em junho."]], ["Entonação na conversa", "Em perguntas com Wh-, a voz desce no fim; em sim ou não, ela sobe.", ["ambition", "My ambition is big."]], ["Next year I ___ going to travel.", "am", "do", "No ano que vem vou viajar.", "Para planos usamos am going to + verbo."]];
