content[350]=[[["Lia walks into the classroom at eight.", "Lia entra na sala de aula às oito."], ["She says, “Good morning, Ravi!”", "Ela diz: “Bom dia, Ravi!”"], ["Ravi says hello and asks, “How are you?”", "Ravi cumprimenta e pergunta: “Como você está?”"], ["Lia is fine, and the class starts.", "Lia está bem, e a aula começa."], ["At noon, Ben says goodbye and see you.", "Ao meio-dia, o Ben diz tchau e até mais."]], [["Good morning, Lia! How are you?", "Bom dia, Lia! Como você está?"], ["Hi, Ravi. I’m fine, thanks.", "Oi, Ravi. Estou bem, obrigada."], ["And you? Are you fine?", "E você? Está bem?"], ["Yes, I’m fine. Hello, Ben!", "Sim, estou bem. Olá, Ben!"], ["Good afternoon. Is class over?", "Boa tarde. A aula acabou?"], ["Yes, it is. Goodbye, everyone!", "Sim, acabou. Tchau, pessoal!"], ["Good night, Lia. See you tomorrow.", "Boa noite, Lia. Até amanhã."], ["Good night, Ravi. See you!", "Boa noite, Ravi. Até mais!"]], ["/h/ em hello e how", "Sopre o ar de leve na garganta, como um suspiro curto, no começo da palavra.", ["hello", "Hello, how are you?"]], ["___ morning, Ravi!", "Good", "Goods", "Bom dia, Ravi!", "Os cumprimentos usam Good no singular: Good morning."]];
