content[351]=[[["Peg is at the front desk.", "A Peg está na recepção."], ["Noah says his first name is Noah.", "O Noah diz que seu nome é Noah."], ["Peg asks, “How do you spell it?”", "A Peg pergunta: “Como se soletra?”"], ["He spells it: N-O-A-H.", "Ele soletra: N-O-A-H."], ["Then he spells his last name.", "Depois ele soletra seu sobrenome."]], [["What is your last name, please?", "Qual é seu sobrenome, por favor?"], ["It’s Brown.", "É Brown."], ["How do you spell it?", "Como se soletra?"], ["It’s B-R-O-W-N.", "É B-R-O-W-N."], ["And your first name?", "E o seu nome?"], ["It’s Daniel, D-A-N-I-E-L.", "É Daniel, D-A-N-I-E-L."], ["Is Daniel spelled with one letter L?", "Daniel tem só uma letra L?"], ["Yes, one letter L at the end.", "Sim, uma letra L no final."]], ["Nomes das letras A, E, I", "A é “êi”, E é “i” longo e I é “ai”. Fale cada letra devagar.", ["spell", "Please spell your name."]], ["How ___ you spell it?", "do", "does", "Como você soletra isso?", "Com you, a pergunta usa do."]];
