content[352]=[[["Tina meets Lou at the club.", "A Tina encontra o Lou no clube."], ["She asks for his phone number.", "Ela pede o número de telefone dele."], ["His number is five, five, zero, twelve.", "O número dele é cinco, cinco, zero, doze."], ["Tina writes the numbers on paper.", "A Tina escreve os números no papel."], ["Then she calls him at twelve.", "Depois ela liga para ele ao meio-dia."]], [["What’s your phone number, Lou?", "Qual é seu telefone, Lou?"], ["It’s five, five, zero, one, two.", "É cinco, cinco, zero, um, dois."], ["Is that zero or the letter O?", "É zero ou a letra O?"], ["It’s zero. Then twelve at the end.", "É zero. Depois doze no final."], ["Is the number twelve or twenty?", "O número é doze ou vinte?"], ["Twelve. T-W-E-L-V-E.", "Doze. D-O-Z-E em inglês: T-W-E-L-V-E."], ["What’s your number, Tina?", "Qual é o seu número, Tina?"], ["It’s seven, nine, eight, fifteen.", "É sete, nove, oito, quinze."]], ["/θ/ e /v/ em three e twelve", "Em twelve, encoste os lábios nos dentes de cima no V. Em three, ponha a língua entre os dentes.", ["twelve", "My phone number has twelve."]], ["What ___ your phone number?", "is", "are", "Qual é seu número de telefone?", "Number é singular, então use is."]];
