content[353]=[[["Ava is in an English class.", "A Ava está numa aula de inglês."], ["Her friend June is thirty years old.", "A amiga June tem trinta anos."], ["Ava asks, “How old is your dad?”", "Ava pergunta: “Quantos anos seu pai tem?”"], ["June says he is fifty.", "A June diz que ele tem cinquenta."], ["Their teacher says, “Count to one hundred!”", "A professora diz: “Contem até cem!”"]], [["How old are you, Ava?", "Quantos anos você tem, Ava?"], ["I’m twenty-five. And you?", "Tenho vinte e cinco. E você?"], ["I’m thirty. My brother is forty.", "Tenho trinta. Meu irmão tem quarenta."], ["Is your mom old?", "Sua mãe é idosa?"], ["No, she’s fifty. Not very old.", "Não, ela tem cinquenta. Não é muito idosa."], ["My grandpa is ninety years old.", "Meu avô tem noventa anos."], ["Wow! Is he one hundred soon?", "Uau! Ele faz cem logo?"], ["No, he’s ninety. Ten more years!", "Não, ele tem noventa. Mais dez anos!"]], ["Acento em thirty e forty", "Nas dezenas -ty, a força fica na primeira sílaba: THIR-ty, FOR-ty, FIF-ty.", ["thirty", "I’m thirty years old."]], ["I ___ twenty-five.", "am", "have", "Eu tenho vinte e cinco anos.", "Em inglês a idade usa be (I am), não have."]];
