content[354]=[[["Nico is new in the English class.", "O Nico é novo na aula de inglês."], ["Lia says, “I’m from Brazil. I’m Brazilian.”", "Lia diz: “Sou do Brasil. Sou brasileira.”"], ["Nico is from Japan, so he is Japanese.", "O Nico é do Japão, então é japonês."], ["Ben is from Canada.", "O Ben é do Canadá."], ["Every country is on the big map.", "Cada país está no mapa grande."]], [["Where are you from, Nico?", "De onde você é, Nico?"], ["I’m from Japan. And you?", "Sou do Japão. E você?"], ["I’m from Brazil. I’m Brazilian.", "Sou do Brasil. Sou brasileira."], ["Is Ben Brazilian too?", "O Ben também é brasileiro?"], ["No, he’s Canadian. He’s from Canada.", "Não, ele é canadense. É do Canadá."], ["Which country is Ava from?", "De que país a Ava é?"], ["She’s American. She’s from here.", "Ela é americana. É daqui."], ["Great! We’re from four countries.", "Ótimo! Somos de quatro países."]], ["/z/ em Brazil e Brazilian", "O Z vibra como em “zebra”. Não troque por S.", ["Brazil", "Lia is from Brazil."]], ["I’m ___ Brazil.", "from", "of", "Sou do Brasil.", "Para dizer a origem, use from, não of."]];
