content[357]=[[["June is a nurse at City Hospital.", "A June é enfermeira no City Hospital."], ["She works with doctors every day.", "Ela trabalha com médicos todos os dias."], ["Lou is a driver, and he works downtown.", "O Lou é motorista e trabalha no centro."], ["Ava is a teacher at a small school.", "A Ava é professora em uma escola pequena."], ["Ben works in an office near the park.", "O Ben trabalha em um escritório perto do parque."]], [["What do you do?", "O que você faz?"], ["I’m a nurse.", "Sou enfermeira."], ["Where do you work?", "Onde você trabalha?"], ["I work at a big hospital.", "Trabalho em um hospital grande."], ["Does Lou work there too?", "O Lou trabalha lá também?"], ["No, he is a driver.", "Não, ele é motorista."], ["What does Ben do?", "O que o Ben faz?"], ["He works in an office.", "Ele trabalha em um escritório."]], ["O som /ɝ/ em nurse e work", "Enrole a língua para trás, sem tocar o céu da boca: o som de “ér”.", ["nurse", "She is a nurse."]], ["She ___ at a hospital.", "works", "work", "Ela trabalha em um hospital.", "Com she, o verbo work ganha -s."]];
